const DOMAINS=[{"id":"food","label":"Food & Agriculture","icon":"🌾","accent":"#87e36a","mission":"Strengthen household, community, farm, ranch, processing and regional food resilience from soil and water through storage, nutrition and distribution.","principle":"Food resilience = production + soil + water + storage + access + logistics + skills + recovery.","actors":["households","producers","ranchers","schools","food banks","processors","grocers","restaurants","counties","researchers"],"modules":["Household food security","Farm & ranch production","Soil health","Irrigation efficiency","Livestock systems","Urban agriculture","School food systems","Cold chain","Storage & preservation","Processing capacity","Distribution & last mile","Food access","Nutrition programs","Farm-to-school","Disaster continuity","Producer finance","Grant navigation","Market resilience","Pollinator habitat","Local seed systems"],"playbook":["Map current food sources and failure points.","Separate production constraints from affordability, logistics and nutrition constraints.","Protect water, soil and cold-chain dependencies first.","Create at least one local continuity option for critical food flows.","Track outcomes such as days of supply, spoilage, access time and producer throughput."],"calc":{"kind":"food","title":"Household reserve estimator","desc":"Planning estimate only. Converts people × days × daily calories into a reserve target and lets you add a spoilage/contingency margin."}},{"id":"water","label":"Water Sovereignty","icon":"💧","accent":"#58c7ff","mission":"Improve water security, affordability, conservation, diversified supply, drought resilience, groundwater stewardship and safe emergency continuity.","principle":"Water sovereignty means resilient, diversified and informed stewardship—not bypassing utilities, public-health rules or water rights.","actors":["households","utilities","farmers","ranchers","schools","industry","watersheds","counties","emergency managers","planners"],"modules":["Household water","Municipal systems","Rural systems","Agriculture","Groundwater","Surface water","Reservoirs","Rainwater harvesting","Reuse","Desalination","Aquifer storage","Watersheds","Drought","Flood capture","Emergency water","Leak reduction","Water quality","Affordability","Regional planning","Evidence library"],"playbook":["Measure demand, supply, losses and critical minimum service.","Fix avoidable leakage before adding expensive supply where practical.","Diversify supply with lawful, quality-controlled sources.","Protect aquifers, watersheds and environmental flows.","Maintain emergency water plans and verify treatment requirements with authorities."],"calc":{"kind":"water","title":"Rain capture estimator","desc":"Planning estimate using roof area, rainfall and a capture-efficiency factor; actual yield varies with first-flush losses, roof design and storage."}},{"id":"energy","label":"Energy & Grid Resilience","icon":"⚡","accent":"#ffd56a","mission":"Reduce energy burden, improve efficiency, understand grid dependencies, plan backup power and coordinate distributed energy and critical-load resilience.","principle":"Energy resilience = efficiency + reliable supply + flexible demand + safe backup + informed coordination.","actors":["households","utilities","schools","hospitals","businesses","industries","local governments","grid planners","emergency managers","researchers"],"modules":["Household energy","Efficiency","Weatherization","Demand response","Solar","Storage","Generators","Microgrids","Critical loads","Grid conditions","Transmission","Distribution","Outage planning","Heat resilience","Winterization","Industrial energy","EV charging","Community energy","Project finance","Safety & codes"],"playbook":["Inventory critical loads and outage consequences.","Reduce demand before sizing backup systems.","Separate short-duration backup from multi-day resilience.","Use qualified electrical design and code-compliant transfer/islanding equipment.","Track outage hours, peak demand, energy cost and critical-service uptime."],"calc":{"kind":"energy","title":"Backup runtime estimator","desc":"Planning estimate for battery energy and critical-load demand. Real runtime depends on inverter losses, temperature, battery limits and surge loads."}},{"id":"housing","label":"Housing Affordability & Resilience","icon":"🏠","accent":"#ffb36a","mission":"Reduce total housing burden, preserve homes, improve supply options, resilience, accessibility and transparent project planning.","principle":"Total housing cost = shelter + taxes + insurance + utilities + maintenance + transportation + required fees.","actors":["renters","homeowners","buyers","landlords","builders","developers","housing counselors","nonprofits","municipalities","counties"],"modules":["Rent burden","Homeownership","Property tax","Insurance","Utilities","Maintenance","Transportation burden","Land & zoning literacy","Permitting","Infill","Starter homes","Multifamily","Manufactured housing","Accessibility","Aging in place","Homelessness prevention","Disaster resilience","Housing pipeline","Affordability scenarios","Assistance navigator"],"playbook":["Calculate the full monthly burden, not only rent or mortgage.","Identify whether the dominant constraint is income, supply, financing, insurance, utility or transport cost.","Compare portfolios of interventions rather than assuming one policy works everywhere.","Preserve existing safe housing while planning new supply.","Track cost burden, displacement risk, unit delivery time and resilience upgrades."],"calc":{"kind":"housing","title":"Total housing burden","desc":"Combines major monthly housing-related costs and compares them with gross household income. It is an educational planning tool, not underwriting advice."}},{"id":"resilience","label":"Community Resilience","icon":"🛡️","accent":"#d69cff","mission":"Prepare for, withstand, respond to and recover from compound hazards while protecting critical functions and reducing cascading failures.","principle":"Resilience = preparedness + redundancy + flexibility + coordination + recovery capacity.","actors":["households","neighborhoods","schools","businesses","utilities","shelters","emergency managers","volunteers","municipalities","counties"],"modules":["Extreme heat","Flooding","Hurricanes","Tornadoes","Wildfire","Drought","Winter storms","Power outages","Water outages","Communications failure","Fuel disruption","Food disruption","Public health events","Evacuation","Sheltering","Continuity of operations","Mutual aid","Recovery","After-action learning","Compound-risk scenarios"],"playbook":["List hazards, then map dependencies and vulnerable people/functions.","Prioritize life safety and continuity of essential services.","Build redundancy across power, water, communications, transport and supply chains.","Document roles, triggers, handoffs and recovery priorities.","After events, capture lessons and convert them into funded mitigation actions."],"calc":{"kind":"resilience","title":"Preparedness coverage check","desc":"A transparent non-predictive score across essential preparedness categories. It does not forecast whether a household or community will be safe."}},{"id":"health","label":"Health Navigator","icon":"✚","accent":"#6fffd4","mission":"Improve navigation of preventive, primary, urgent, behavioral, maternal/child, rural and public-health resources while connecting health to housing, food, mobility and connectivity.","principle":"Health access depends on timely care + affordability + transportation + information + continuity + trusted public-health guidance.","actors":["individuals","families","clinics","hospitals","schools","community health workers","public health","nonprofits","counties","researchers"],"modules":["Care navigation","Primary care","Urgent care literacy","Emergency care boundaries","Preventive care","Maternal & child health","Behavioral health resources","Rural access","Telehealth readiness","Medication continuity","Heat health","Air quality","Water & sanitation","Food & nutrition","Disability access","Language access","Transportation to care","Public-health alerts","Community health workers","Evidence literacy"],"playbook":["For emergencies, use emergency services rather than the planner.","Separate access barriers from medical diagnosis.","Map care, transport, affordability, language and connectivity constraints.","Prefer current official clinical/public-health guidance for high-stakes decisions.","Track appointment access, travel burden, continuity gaps and service availability."],"calc":{"kind":"health","title":"Health access friction map","desc":"Scores practical access barriers such as travel, scheduling, cost and connectivity. It does not diagnose illness or estimate medical risk."}},{"id":"insurance","label":"Household & Insurance Resilience","icon":"☂️","accent":"#ff8ea3","mission":"Reduce household financial vulnerability by connecting insurance literacy, mitigation, savings, maintenance, documentation and recovery planning.","principle":"Protection + preparedness + savings + maintenance + documentation + recovery capacity.","actors":["renters","homeowners","families","seniors","landlords","small businesses","housing counselors","disaster survivors","community organizations","local governments"],"modules":["Policy literacy","Deductibles","Coverage limits","Exclusions","Replacement cost","Actual cash value","Flood insurance","Wind & hail","Wildfire","Home inventory","Claims documentation","Emergency savings","Maintenance planning","Roof resilience","Freeze protection","Contractor risk","Temporary housing","Recovery finance","Fraud awareness","Assistance navigator"],"playbook":["Document assets, property condition and policy information before loss.","Separate damage prevention, risk reduction, insurance transfer and self-funded reserves.","Review deductibles, exclusions and coverage limits with licensed professionals when needed.","Preserve receipts, photos, communications and repair records after a loss.","Track mitigation completion, reserve adequacy and unresolved recovery gaps."],"calc":{"kind":"insurance","title":"Recovery gap estimator","desc":"Compares a user-entered loss scenario with coverage, deductible and liquid reserves. Policy terms control actual claim outcomes."}},{"id":"mobility","label":"Mobility & Transportation","icon":"🚌","accent":"#8fb7ff","mission":"Improve safe, reliable, affordable and accessible access to jobs, schools, healthcare, food, services and emergency routes across urban and rural Texas.","principle":"Mobility success is access to essential destinations—not vehicle speed alone.","actors":["commuters","students","seniors","people with disabilities","employers","freight","transit agencies","planners","emergency managers","local governments"],"modules":["Household transport burden","Trip planning","Road safety","Transit","Paratransit","Walking","Cycling","School transportation","Rural mobility","Freight","First/last mile","EV charging","Fleet transition","Infrastructure condition","Congestion","Access to jobs","Access to healthcare","Evacuation","Project pipeline","Data & maps"],"playbook":["Start with destinations people need to reach and the cost/time/reliability of reaching them.","Measure multimodal access, not only road throughput.","Identify groups excluded by vehicle ownership, disability, distance or schedule.","Plan evacuation and freight continuity as critical resilience functions.","Track travel time, household cost, safety, accessibility and service reliability."],"calc":{"kind":"mobility","title":"Mobility burden estimator","desc":"Combines monthly transport spending and travel time to expose affordability and access burden. It does not value time as a wage unless the user elects to."}},{"id":"learning","label":"Learning & Teacher Capacity","icon":"🎓","accent":"#c9ff6a","mission":"Strengthen teacher pipelines, student opportunity, tutoring, CTE, dual credit, inclusive learning, school operations and cross-sector education capacity.","principle":"Education capacity = educators + learning time + support + pathways + access + safe enabling infrastructure.","actors":["students","families","teachers","school leaders","districts","ESCs","higher education","employers","libraries","nonprofits"],"modules":["Teacher pipeline","Certification","Professional learning","Teacher retention","Tutoring","Student opportunity","CTE","Dual credit","Work-based learning","Libraries","Inclusive learning","Special populations","School operations","Transportation","Housing & teacher retention","Health & attendance","Food & learning","Energy & schools","Water & schools","Connectivity & homework"],"playbook":["Map educator capacity and student access by subject, location and pathway.","Distinguish recruitment, certification, hiring, induction and retention bottlenecks.","Connect learning opportunities to transport, broadband, health, food and housing realities.","Use privacy-safe aggregate data for collaboration.","Track educator vacancies, student participation, completion and pathway transitions."],"calc":{"kind":"learning","title":"Teacher capacity scenario","desc":"A simplified planning model for vacancies, hires and retention. It is not an official staffing forecast."}},{"id":"connectivity","label":"Connectivity & Opportunity","icon":"📡","accent":"#67f0ff","mission":"Improve broadband access, affordability, devices, skills, reliability and digital opportunity for education, health, work, business and emergency communication.","principle":"Digital opportunity = access + affordability + devices + skills + reliability + safety + useful services.","actors":["households","students","teachers","workers","libraries","clinics","small businesses","broadband planners","communities","researchers"],"modules":["Broadband access","Affordability","Speed & reliability","Rural connectivity","Public Wi-Fi","Device access","Refurbishment","Digital literacy","Cyber safety","Accessibility","Education access","Telehealth","Workforce access","Remote work","Small business","Emergency connectivity","Community networks","Broadband mapping","Project pipeline","Funding navigation"],"playbook":["Separate availability, affordability, device, skills and reliability barriers.","Use measured experience and official map data together; neither alone proves the full picture.","Provide backup communication paths for critical services.","Connect broadband projects to concrete outcomes such as education, care, work and emergency access.","Track locations served, reliability, adoption, affordability and service activation."],"calc":{"kind":"connectivity","title":"Digital opportunity diagnostic","desc":"Classifies the user-entered barrier mix across access, affordability, device, skills and reliability. It does not verify provider coverage."}}];
