const GUIDES=[{"id":"systems","title":"Systems-of-systems design","one":"A project is rarely only a water, housing or energy project. Start with the outcome, then map dependencies across all ten domains.","steps":["Name the outcome and affected population.","Select the domains that can block success.","Record one measurable dependency per selected domain.","Assign owners and evidence.","Review the dependency map before major decisions."],"advanced":"Use causal-loop thinking: identify reinforcing and balancing feedbacks, bottlenecks, lagging indicators and failure cascades. Keep observations separate from hypotheses.","expert":"Represent projects as typed nodes with dependency edges, evidence provenance, revision timestamps and explicit assumptions. Avoid centralizing protected or unnecessary personal data."},{"id":"trystero","title":"Trystero / WebRTC collaboration","one":"Trystero helps browsers discover peers; after connection, project data travels browser-to-browser over WebRTC.","steps":["Choose a non-sensitive room ID.","Use a shared password for private working groups.","Start with Nostr discovery; try MQTT/Torrent/IPFS only when there is a reason.","Connect two devices and exchange a harmless test message.","Configure TURN only if direct connectivity repeatedly fails."],"advanced":"The build uses Trystero 0.25.3 action objects, presence hooks, snapshot requests and room-scoped event exchange. Discovery still requires network infrastructure even though app traffic is peer-to-peer.","expert":"For controlled environments, replace public discovery with the Trystero WebSocket-relay strategy and your own relay. Evaluate NAT behavior, TURN cost, browser limits, logging policy and data-retention requirements."},{"id":"pwa","title":"PWA & offline architecture","one":"The app shell and locally created records can work offline after a hosted first load; live agencies, multiplayer discovery and uncached AI models cannot.","steps":["Serve the folder over HTTPS or localhost.","Install the PWA after the first complete load.","Export a JSON backup before major browser/device changes.","Check the freshness badge before relying on time-sensitive links."],"advanced":"The service worker uses versioned same-origin app-shell caching and network-first navigation with offline fallback. IndexedDB stores structured local records; localStorage stores small preferences.","expert":"Do not use service-worker claims under file://. Treat cross-origin CDN libraries and model artifacts as online dependencies unless explicitly cached by their own mechanisms."},{"id":"webllm","title":"Local WebLLM assistant","one":"WebLLM can run an LLM locally in a compatible browser using WebGPU, keeping prompts on-device after the library/model is loaded.","steps":["Confirm WebGPU support and review browser storage capacity.","Open Local AI Lab and load the compatible model catalog.","Sort by declared VRAM requirement and start with a smaller model than your device limit suggests.","Download/cache a model or load it directly into the dedicated worker.","Use it for drafting or organizing—not authoritative live facts—and verify outputs against the evidence library."],"advanced":"The assistant runs in a dedicated module worker and uses WebLLM 0.2.85. The model manager reads WebLLM’s prebuilt registry, shows declared VRAM requirements, cache status and persistent-storage controls, and supports Cache API, IndexedDB and OPFS backends.","expert":"Treat declared VRAM as a planning indicator rather than a guarantee. Preserve the runtime’s compatible model registry, separate cache/storage state from GPU-loaded state, expose delete/unload controls, and build source-grounding or retrieval separately if authoritative citations are required."},{"id":"evidence","title":"Evidence & provenance","one":"Every important claim should be traceable to a source, date, jurisdiction and limitation.","steps":["Record the source URL and retrieval date.","Label facts, estimates, scenarios and hypotheses separately.","Prefer official/primary sources for program status and public data.","Mark stale or locally unverified information.","Attach evidence to the decision it informed."],"advanced":"Use an append-only evidence log with revisions, content hashes and structured claim/source relationships. A hash detects change; it does not prove who authored the content.","expert":"For stronger provenance, combine hashes with signatures, trusted timestamps and source-side identifiers. Preserve source licenses and do not imply a cryptographic hash establishes truth."},{"id":"mapping","title":"Mapping challenges","one":"Maps are models. Coverage, hazard, service and project layers can be useful without being perfectly current or precise.","steps":["Identify the map owner and update date.","Check whether a point, parcel, block or area is the actual unit.","Compare mapped status with observed conditions.","Document discrepancies with non-sensitive evidence.","Use the official challenge/correction workflow where available."],"advanced":"Avoid false precision. Distinguish service availability, adoption, measured performance, planned construction and operational status.","expert":"For interoperable GIS work, store source CRS, geometry precision, update cadence, confidence, licensing and transformation history."},{"id":"collab","title":"Multidisciplinary project design","one":"Effective teams translate each discipline into constraints, evidence and handoffs instead of forcing everyone into one vocabulary.","steps":["Choose a shared outcome.","Assign disciplinary roles.","Create a dependency board.","Record decisions and open questions.","Schedule evidence-based review gates."],"advanced":"Use boundary objects—shared artifacts such as maps, budgets, risk registers and outcome metrics—that each discipline can interpret without erasing domain-specific nuance.","expert":"Define interface contracts between modules: inputs, outputs, units, uncertainty, update cadence, owner, escalation path and failure behavior."},{"id":"broadband","title":"Texas broadband project status","one":"Texas’ BEAD final proposal is approved; use official BDO project files for location- and award-specific status rather than assuming a statewide announcement means service is active.","steps":["Open the official BEAD source.","Identify the relevant deployment project or serviceable locations.","Separate award, construction and activation status.","Record local evidence and dates.","Do not promise availability until the provider/project confirms service."],"advanced":"A broadband project pipeline should distinguish need → challenge/validation → award → engineering → permitting → construction → activation → adoption.","expert":"Cross-check official project IDs, location fabric versions, challenge outcomes, award amendments and provider reporting before longitudinal analysis."},{"id":"safety","title":"Privacy, safety & protected data","one":"The commons is for coordination data, not protected case records or secrets.","steps":["Share the minimum information needed.","Keep health, student, policy, credential and identity-sensitive records out of public/P2P rooms.","Use pseudonymous project IDs where possible.","Do not paste API keys or passwords into shared records.","Export and review local data before sharing."],"advanced":"A P2P architecture changes data paths but does not remove confidentiality obligations. Peers can still receive whatever you choose to send.","expert":"Threat-model signaling metadata, peer identity, room-name guessing, browser storage, TURN relays, imported JSON, XSS, link handling and operator access."},{"id":"recovery","title":"Continuity & recovery","one":"Design for degraded operation before failure occurs.","steps":["Name the critical function.","Define its minimum viable service.","List dependencies and single points of failure.","Create manual/offline alternatives.","Set recovery order and evidence capture."],"advanced":"Use recovery-time and recovery-point objectives where applicable, but translate them into human-readable service goals for public-facing teams.","expert":"Model cross-domain common-cause failures and correlated hazards; redundancy is not real if all backups depend on the same upstream system."},{"id":"governance","title":"Decision governance","one":"Good collaboration makes it clear who can decide, who must be consulted, and how evidence changes a decision.","steps":["Name the decision owner.","List affected parties.","Attach evidence and assumptions.","Record alternatives and tradeoffs.","Set a review trigger/date."],"advanced":"Separate governance roles from technical roles. A technically strong option may still require legal authority, financing, public process or operational capacity.","expert":"Use decision records with status, jurisdiction, authority basis, dissent/uncertainty notes, revision lineage and implementation evidence."}];
GUIDES.push(...[{"id":"snapshot-sync","title":"Peer snapshot synchronization","one":"When a new participant joins a room, peers can answer a snapshot request with their current shared coordination records so the newcomer does not need a central application database.","steps":["Join with a non-sensitive room ID.","Let snapshot exchange complete before editing shared records.","Review received projects/tasks/decisions/comments.","Resolve conflicts using revision and update timestamps.","Export a local JSON backup before major merges."],"advanced":"This build uses a Trystero request action for state snapshots. Every peer can respond with a sanitized, bounded snapshot. Received records pass the same schema whitelist used by file imports.","expert":"Snapshot sync is eventual, peer-provided state\u2014not consensus. For stronger consistency, add signed operation logs, vector/Lamport clocks, CRDTs or an authoritative service appropriate to the governance requirements."},{"id":"turn","title":"TURN as explicit fallback","one":"WebRTC usually connects peers directly, but some NAT/firewall combinations require TURN. TURN relays packets when direct connectivity cannot be established.","steps":["Try direct connection first.","If SDP is exchanged but peers never connect, review Trystero join errors.","Add a TURN URL and short-lived credentials only when needed.","Test across real institutional networks.","Monitor relay cost and retention/logging policy."],"advanced":"Trystero accepts turnConfig while retaining its default STUN servers. TURN is transport fallback, not hidden application storage; peer traffic remains WebRTC encrypted, but a relay still observes transport metadata.","expert":"Use time-limited TURN credentials, TLS where supported, capacity planning, abuse controls and regional failover. Treat TURN operator access and network metadata as part of the threat model."},{"id":"public-room","title":"Public Commons and unverified presence","one":"The default public room is a rendezvous for collaboration presence. A Trystero peer ID proves only that a browser peer is connected; it does not verify a person's name, employer or authority.","steps":["Do not trust role labels as identity proof.","Share no protected records in the public room.","Use a password-protected private room for working groups.","Verify organizational identity out-of-band for consequential decisions.","Record authoritative decisions in your formal system of record."],"advanced":"Pseudonymous presence can support discovery and lightweight collaboration, but identity assurance is a separate system. Room passwords strengthen session-description encryption and access by shared secret; they do not establish institutional identity.","expert":"For higher assurance, add an explicit admission handshake with signed organizational keys, short-lived credentials or an institution-managed identity layer while preserving data-minimization principles."},{"id":"broadband-projects","title":"Texas broadband project pipeline","one":"Texas now has overlapping broadband programs at different stages. Treat award, construction, activation and adoption as separate states.","steps":["Start with BDO BEAD/BOOT award files.","Locate the project/location identifier.","Check the latest completion status or grant agreement.","Compare FCC-map claims with local evidence.","Record activation only after service is actually orderable/confirmed."],"advanced":"BEAD, BOOT, pole replacement, middle-mile, local utility work and private construction can interact. A project registry should record program, awardee, geography, technology, stage, dependencies, challenge history and freshness date.","expert":"For longitudinal analysis, version the underlying FCC Fabric/location set and preserve award amendments. Avoid comparing location counts across Fabric versions without documenting the change in the denominator."},{"id":"multidisciplinary","title":"Institution-to-family collaboration design","one":"Cross-domain work succeeds when every participant knows what they contribute, what they need from others, and what constitutes an accepted handoff.","steps":["Name the shared outcome.","List families, businesses, institutions, operators and government roles.","Define inputs/outputs for each role.","Create tasks, open questions and handoffs.","Record decisions with evidence and review triggers."],"advanced":"Use the project record as a boundary object. Keep discipline-specific detail in its native language, but normalize interface fields: owner, input, output, units, deadline, evidence, uncertainty and acceptance condition.","expert":"Model the collaboration as a typed dependency graph. Separate governance authority, technical responsibility, funding responsibility, operations responsibility and affected-party voice; they are often held by different actors."},{"id":"data-sovereignty","title":"Data sovereignty and conflict resolution","one":"Local-first means your browser holds the working record by default. Sharing is explicit, backups are portable, and no automatic cloud account is required for core functions.","steps":["Export JSON backups regularly.","Keep sensitive records out of peer rooms.","Review imported schema before merge.","Use revisions/timestamps to resolve ordinary conflicts.","Preserve authoritative external records in their official systems."],"advanced":"This build whitelists fields, limits imported file size and sanitizes peer records. Local-first is not the same as infallible persistence\u2014browser storage can be cleared or evicted.","expert":"For institutional deployment add retention policies, encrypted-at-rest storage where justified, signed exports, migration tests, access-control boundaries and a documented conflict-resolution authority."}]);

GUIDES.push(
{id:'actionable-nexus',title:'Actionable Cross-Domain Nexus',one:'The Nexus turns a shared outcome into system dependencies, baseline tasks and explicit interface handoffs that can be saved directly into the coordination board.',steps:['Write one measurable outcome.','Select at least two systems that can enable or block it.','Generate the dependency plan.','Review each interface for owner, evidence, threshold and acceptance condition.','Save the plan as executable tasks/handoffs and close them through the coordination board.'],advanced:'Treat each cross-domain edge as an interface contract. A dependency is actionable only when the supplying system, receiving system, unit/threshold, responsible owner, evidence and failure/escalation behavior are explicit.',expert:'Use typed dependency edges and boundary objects; preserve uncertainty and jurisdiction. For complex programs, migrate the generated interfaces to a graph/CRDT or portfolio system with explicit authority, resource and review metadata.'},
{id:'cascade-to-action',title:'Cascade Lab → action conversion',one:'The Cascade Lab is a transparent stress-propagation heuristic that now produces prioritized interventions, evidence questions, handoffs and a project/quest conversion path.',steps:['Enter only the stressors you want to explore.','Set duration and readiness.','Inspect propagated planning scores and the disclosed heuristic.','Review generated actions and evidence questions.','Convert the scenario into a project, tasks and handoffs only after local validation.'],advanced:'The model intentionally does not estimate probability. It propagates entered stress through a fixed dependency graph, then applies duration amplification and readiness reduction. The resulting scores are prioritization prompts, not calibrated risk.',expert:'Replace heuristic weights with locally validated dependency matrices, fragility curves, service thresholds or probabilistic/agent-based models only when evidence supports that complexity. Keep scenario assumptions versioned and auditable.'}
);
const STATUS_FACTS=[{"domain":"connectivity","asOf":"2026-09-28","title":"Texas BEAD final proposal approved","status":"approved / grant-agreement and construction phase","fact":"Texas states that its BEAD Final Proposal was approved Dec. 4, 2025. The BDO selected 22 applicants to serve more than 240,000 broadband serviceable locations and more than 2,700 community anchor institutions, with $1.2 billion in federal grants and $177 million in state match; the BDO said projects could begin construction as soon as summer 2026.","source":"Texas Broadband Development Office","url":"https://comptroller.texas.gov/programs/broadband/funding/bead/","limits":"Award and proposal approval are not the same as active service at a specific address. Verify project/location status in official award files and with the provider."},{"domain":"connectivity","asOf":"2026-09-28","title":"BOOT I and II infrastructure programs","status":"awarded / implementation","fact":"BOOT I reports $10.4 million awarded for 1,468 residential locations, 77 businesses and 15 community anchor institutions, with BOOT I projects due by Dec. 31, 2026. BOOT II reports $623.4 million awarded for 61,185 residential locations, 18,250 businesses and 2,191 community anchor institutions.","source":"Texas Broadband Development Office","url":"https://comptroller.texas.gov/programs/broadband/funding/boot/","limits":"Completion status is project-specific and updated by BDO; awarded locations are not automatically active connections."},{"domain":"connectivity","asOf":"2026-08-12","title":"FCC broadband map remains challengeable","status":"ongoing data-quality process","fact":"The FCC Broadband Data Collection allows individuals to challenge a single Fabric location through the National Broadband Map, while governments and other eligible entities can submit bulk Fabric challenges through the BDC system.","source":"FCC Broadband Data Collection Help Center","url":"https://help.bdc.fcc.gov/hc/en-us/articles/8103890293275-How-to-Format-a-Bulk-Fabric-Challenge","limits":"The map reports provider-claimed availability; it is not a direct measure of affordability, adoption or experienced performance."},{"domain":"water","asOf":"2026-09-28","title":"2027 State Water Plan adopted","status":"adopted Phase I; amendment process continuing","fact":"The Texas Water Development Board adopted the 2027 State Water Plan on July 23, 2026. It is based on all 16 regional water planning groups and identifies actionable strategies and projects with projected costs and sponsors.","source":"Texas Water Development Board","url":"https://www.twdb.texas.gov/waterplanning/swp/2027/","limits":"Some recommended project locations are planning-level or conceptual; project siting and implementation still require subsequent studies, approvals, financing and sponsor action."},{"domain":"water","asOf":"2026-09-28","title":"2026 regional water plans approved","status":"approved","fact":"TWDB states that the adopted 2026 Regional Water Plans were approved by the Board on Jan. 22, 2026, covering Regions A through P and feeding the 2027 state planning cycle.","source":"Texas Water Development Board","url":"https://www.twdb.texas.gov/waterplanning/rwp/plans/2026/index.asp","limits":"Regional planning projections and recommended strategies are planning inputs, not guarantees of project delivery or future hydrologic conditions."},{"domain":"energy","asOf":"2026-09-28","title":"ERCOT resource adequacy reporting","status":"ongoing monthly / periodic reporting","fact":"ERCOT's resource adequacy page identifies the Monthly Outlook for Resource Adequacy (MORA) as its current recurring outlook and publishes Capacity, Demand and Reserves reports plus generation-resource capacity forecasts.","source":"ERCOT","url":"https://www.ercot.com/gridinfo/resource","limits":"Resource adequacy reports are system-planning products and should not be interpreted as a guarantee of service to a particular customer or facility."},{"domain":"housing","asOf":"2026-09-28","title":"2026 Texas low-income housing plan and annual report","status":"current annual planning reference","fact":"TDHCA's 2026 State of Texas Low Income Housing Plan and Annual Report provides a statewide housing-needs overview and reports on program administration, funding levels and resource distribution from the preceding fiscal year.","source":"Texas Department of Housing and Community Affairs","url":"https://www.tdhca.texas.gov/housing-resource-center-annual-or-biennial-plans-and-reports","limits":"Statewide and regional summaries do not substitute for local market, zoning, infrastructure, condition or household-level analysis."},{"domain":"resilience","asOf":"2026-09-28","title":"Texas hazard-mitigation planning framework","status":"active program","fact":"TDEM maintains the State Hazard Mitigation Plan, reviews local mitigation plans and administers FEMA mitigation programs. TDEM notes that a FEMA-approved local hazard mitigation plan is required for eligibility under specified FEMA mitigation grants such as HMGP and BRIC.","source":"Texas Division of Emergency Management","url":"https://www.tdem.texas.gov/mitigation/hazard-mitigation-section","limits":"Grant availability and eligibility vary by disaster, funding cycle, jurisdiction and federal/state rules; verify current notices before planning around funding."},{"domain":"health","asOf":"2026-09-28","title":"Texas Health Data public dashboards","status":"active public data platform","fact":"Texas DSHS provides public interactive dashboards through Texas Health Data, including maternal health, infant health, respiratory illness and other topic-specific datasets and reports.","source":"Texas Department of State Health Services","url":"https://healthdata.dshs.texas.gov/","limits":"Public-health dashboards may use different reporting periods, definitions and suppression rules; they are not a substitute for clinical diagnosis or emergency guidance."},{"domain":"insurance","asOf":"2026-09-28","title":"Texas homeowners insurance market snapshot","status":"2025 preliminary / 2026 filing snapshot","fact":"TDI's market overview reports 8,233,096 active homeowners policies in 2025, an average annual homeowners premium of $3,489, and a -1.8% aggregate filed rate request for June-August 2026 on the page's current snapshot.","source":"Texas Department of Insurance","url":"https://tdi.texas.gov/general/texas-homeowners-insurance-market-overview.html","limits":"Statewide averages do not represent a quote, renewal outcome or risk profile for a specific property; policy terms and geography can materially change cost and coverage."},{"domain":"mobility","asOf":"2026-09-28","title":"Texas statewide long-range transportation planning","status":"2050 plan framework","fact":"TxDOT describes the statewide long-range transportation plan as a 24-year multimodal planning blueprint and states that the SLRTP is updated every four years.","source":"Texas Department of Transportation","url":"https://www.txdot.gov/manuals/tpp/tpp/statewide_longrange_transportation_plan.html","limits":"Long-range plans guide strategy and performance; individual projects have separate development, environmental, funding and construction timelines."},{"domain":"learning","asOf":"2026-09-28","title":"Texas educator data refreshed during 2026","status":"current dashboard releases","fact":"TEA lists the Newly Certified by Role dashboard/data as updated September 2026, Employed and Certified Teachers data as updated August 2026, and Teacher Retention/Attrition New Hires data as updated April 2026.","source":"Texas Education Agency","url":"https://tea.texas.gov/data-reports/educator-data/educator-reports-and-data","limits":"Statewide dashboards require local district/campus context before drawing staffing or program conclusions."},{"domain":"food","asOf":"2026-09-28","title":"Texas agriculture grant and service portfolio","status":"active program directory","fact":"The Texas Department of Agriculture maintains statewide program directories spanning agricultural finance, production grants, nutrition/food-access grants, rural health grants and small-business/export assistance.","source":"Texas Department of Agriculture","url":"https://texasagriculture.gov/Grants-Services/Grants-and-Services","limits":"Program windows, eligibility, appropriations and application requirements change; verify the current notice before treating a program as available."},{"domain":"cross-domain","asOf":"2026-01-20","title":"LCRA broadband + flood-monitoring grant illustrates cross-domain infrastructure","status":"grant announced","fact":"Texas BDO announced a $29 million grant to the Lower Colorado River Authority to expand rural high-speed internet and strengthen flood-monitoring infrastructure, explicitly linking connectivity, emergency management and regional infrastructure.","source":"Texas Comptroller / Broadband Development Office","url":"https://comptroller.texas.gov/about/media-center/news/20260120-acting-texas-comptroller-kelly-hancock-announces-broadband-development-office-29-million-grant-to-lower-colorado-river-authority-1766177275951","limits":"Announcement-level information does not establish construction completion, operating performance or service availability at any particular location."}];
const ROLE_CATALOG=[{"id":"family","label":"Families / households","contributes":["lived experience","local observations","household constraints","adoption feedback"],"needs":["plain language","privacy","affordability","accessibility"],"handoff":"community organizations / service providers"},{"id":"business","label":"Local businesses / employers","contributes":["operational demand","workforce needs","supply-chain constraints","co-investment"],"needs":["reliability","cost clarity","permitting timelines","business continuity"],"handoff":"economic development / utilities / education"},{"id":"corporation","label":"Corporations / infrastructure operators","contributes":["capital","engineering","network operations","procurement capacity"],"needs":["standards","clear interfaces","risk allocation","community evidence"],"handoff":"government / local partners / suppliers"},{"id":"education","label":"Schools / colleges / universities","contributes":["research","training","facilities","student/workforce pathways"],"needs":["student privacy","accessibility","stable connectivity","community partners"],"handoff":"employers / agencies / families"},{"id":"government","label":"State / county / municipal government","contributes":["authority","public data","planning","permitting","grant administration"],"needs":["lawful process","audit trail","public accountability","jurisdiction clarity"],"handoff":"operators / institutions / public"},{"id":"nonprofit","label":"Nonprofits / community organizations","contributes":["trusted relationships","outreach","navigation","mutual aid"],"needs":["referral clarity","funding continuity","minimal data collection","local evidence"],"handoff":"families / agencies / institutions"},{"id":"research","label":"Researchers / technical experts","contributes":["measurement","evaluation","models","standards"],"needs":["provenance","uncertainty labels","method transparency","data governance"],"handoff":"decision owners / implementers"},{"id":"emergency","label":"Emergency management / public safety","contributes":["incident command","continuity planning","warnings","resource coordination"],"needs":["interoperability","offline modes","trusted contacts","clear triggers"],"handoff":"utilities / health / transport / communities"}];
const PUBLIC_ROOM='texas-systems-public-commons-v2';
const ROUTES=[
  {id:'home',label:'Command Center',icon:'✦',group:'Master'},
  {id:'nexus',label:'Cross-Domain Nexus',icon:'◎',group:'Master'},
  {id:'chains',label:'Meta-Chain Studio',icon:'⛓',group:'Master'},
  {id:'status',label:'Texas Status & Evidence',icon:'◉',group:'Master'},
  {id:'projects',label:'Project Commons',icon:'▦',group:'Work'},
  {id:'coordination',label:'Coordination Board',icon:'⇄',group:'Work'},
  {id:'quests',label:'Collaboration Quests',icon:'✧',group:'Work'},
  {id:'evidence',label:'Evidence Ledger',icon:'≣',group:'Work'},
  {id:'decisions',label:'Decision Records',icon:'✓',group:'Work'},
  {id:'scenario',label:'Cascade Lab',icon:'⌁',group:'Work'},
  {id:'guides',label:'Advanced Guides',icon:'⌘',group:'Learn'},
  {id:'ai',label:'Local AI Lab',icon:'◈',group:'Learn'},
  ...DOMAINS.map(d=>({id:'domain-'+d.id,label:d.label,icon:d.icon,group:'Ten Systems'})),
  {id:'about',label:'Architecture & Safety',icon:'§',group:'System'}
];
const routeMap=Object.fromEntries(ROUTES.map(r=>[r.id,r]));
const STORES=['projects','tasks','comments','evidence','decisions','questions','handoffs','quests','chains','chainRuns','chainArtifacts'];
const state={route:'home',db:null,records:Object.fromEntries(STORES.map(k=>[k,[]])),collab:null,settings:{theme:'dark',reduceMotion:false,textScale:1,userMode:'community',skipSplash:false,autoPublicRoom:true}};
const $=(s,el=document)=>el.querySelector(s); const $$=(s,el=document)=>[...el.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));
const uid=(p='id')=>p+'_'+crypto.getRandomValues(new Uint32Array(2)).join('_')+'_'+Date.now();
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>t.classList.remove('show'),3200)}
function currentRoute(){return (location.hash.replace(/^#\/?/,'').split('?')[0]||'home')}
function nav(id){location.hash='#/'+id}
function saveSettings(){localStorage.setItem('txmaster.settings',JSON.stringify(state.settings));applySettings()}
function loadSettings(){try{Object.assign(state.settings,JSON.parse(localStorage.getItem('txmaster.settings')||'{}'))}catch{}applySettings()}
function applySettings(){document.body.classList.toggle('light',state.settings.theme==='light');document.body.classList.toggle('reduce-motion',!!state.settings.reduceMotion);document.documentElement.style.fontSize=(15*Number(state.settings.textScale||1))+'px'}

// ---------- IndexedDB with graceful fallback ----------
function openDB(){return new Promise(resolve=>{if(!('indexedDB'in window)) return resolve(null);const q=indexedDB.open('texas-master-os',5);q.onupgradeneeded=e=>{const db=e.target.result;STORES.forEach(n=>{if(!db.objectStoreNames.contains(n))db.createObjectStore(n,{keyPath:'id'})})};q.onsuccess=()=>resolve(q.result);q.onerror=()=>resolve(null)})}
function dbAll(store){return new Promise(resolve=>{if(!state.db)return resolve([]);const q=state.db.transaction(store,'readonly').objectStore(store).getAll();q.onsuccess=()=>resolve(q.result||[]);q.onerror=()=>resolve([])})}
function dbPut(store,obj){return new Promise(resolve=>{if(!state.db){const a=state.records[store];const i=a.findIndex(x=>x.id===obj.id);if(i>=0)a[i]=obj;else a.push(obj);return resolve(true)};const q=state.db.transaction(store,'readwrite').objectStore(store).put(obj);q.onsuccess=()=>resolve(true);q.onerror=()=>resolve(false)})}
function dbDelete(store,id){return new Promise(resolve=>{if(!state.db){state.records[store]=state.records[store].filter(x=>x.id!==id);return resolve(true)};const q=state.db.transaction(store,'readwrite').objectStore(store).delete(id);q.onsuccess=()=>resolve(true);q.onerror=()=>resolve(false)})}
async function reloadRecords(){for(const n of STORES)state.records[n]=await dbAll(n)}

// ---------- splash ----------
function initSplash(){const s=$('#splash'),bar=$('#splashProgress'),stages=$$('#stageLine b');if(!s)return;let i=0,timer=null,autoTimer=null,joined=false;const joinOnce=()=>{if(joined)return;joined=true;autoJoinPublicRoom()};const closeSplash=(reason='app')=>{if(window.__txCloseSplash)window.__txCloseSplash(reason);else{s.classList.add('hidden');s.setAttribute('aria-hidden','true');document.body.classList.add('splash-closed');setTimeout(()=>s.style.display='none',650)}joinOnce()};window.addEventListener('tx:splashclosed',joinOnce,{once:true});if(document.body.classList.contains('splash-closed')){joinOnce();return}if(state.settings.skipSplash){closeSplash('saved-preference');return}const advance=()=>{if(document.body.classList.contains('splash-closed'))return;if(i<stages.length){stages.forEach((x,j)=>x.classList.toggle('active',j<=i));if(bar)bar.style.width=((i+1)/stages.length*100)+'%';i++;timer=setTimeout(advance,state.settings.reduceMotion?70:560)}else{s.dataset.ready='1';autoTimer=setTimeout(()=>closeSplash('progress-complete'),state.settings.reduceMotion?180:900)}};timer=setTimeout(advance,120);$('#enterBtn')?.addEventListener('click',()=>closeSplash('enter-app'));$('#skipBtn')?.addEventListener('click',()=>closeSplash('skip-app'))}

function renderSidebar(){const by={};ROUTES.forEach(r=>(by[r.group]??=[]).push(r));$('#sidebar').innerHTML=Object.entries(by).map(([g,rs])=>`<div class="side-section"><div class="side-title">${esc(g)}</div>${rs.map(r=>`<a class="nav-link ${state.route===r.id?'active':''}" href="#/${r.id}"><span class="ico">${r.icon}</span><span>${esc(r.label)}</span></a>`).join('')}</div>`).join('')}
function breadcrumb(label){return `<div class="crumbs">Texas Master Systems OS / ${esc(label)}</div>`}
function hero(eyebrow,title,desc,actions=''){return `<section class="hero"><div class="eyebrow">${esc(eyebrow)}</div><h1>${esc(title)}</h1><p>${esc(desc)}</p>${actions?`<div class="hero-actions">${actions}</div>`:''}</section>`}
function domainCards(){return `<div class="domain-grid">${DOMAINS.map(d=>`<a class="domain-card" style="--accent:${d.accent}" href="#/domain-${d.id}"><div class="bigicon">${d.icon}</div><h3>${esc(d.label)}</h3><p>${esc(d.mission)}</p><span class="tag">${d.modules.length} modules</span></a>`).join('')}</div>`}

function renderHome(){const localCount=STORES.reduce((n,k)=>n+state.records[k].length,0);return breadcrumb('Command Center')+hero('Systems-of-systems workspace','Texas Master Systems OS','A unified local-first operating environment for ten essential Texas systems—built for households, institutions, governments, businesses, educators, corporations, researchers and multidisciplinary teams.',`<button class="btn primary" data-go="chains">Open Meta-Chain Studio</button><button class="btn" data-go="nexus">Open the Nexus</button><button class="btn" data-go="projects">Create a project</button><button class="btn" data-open-collab>Open collaboration</button>`)+`<div class="kpis"><div class="kpi"><span class="muted">Systems</span><strong>10</strong><small>one shared shell</small></div><div class="kpi"><span class="muted">Domain modules</span><strong>${DOMAINS.reduce((a,d)=>a+d.modules.length,0)}</strong><small>searchable pathways</small></div><div class="kpi"><span class="muted">Coordination records</span><strong>${localCount}</strong><small>${STORES.length} local-first stores</small></div><div class="kpi"><span class="muted">Official status anchors</span><strong>${STATUS_FACTS.length}</strong><small>dated ${SNAPSHOT}</small></div></div>${collabHUD()}<section class="card span12"><div class="sync-strip"><div><b>Public Commons</b><br><span class="muted">${state.settings.autoPublicRoom?'Auto-connect enabled':'Auto-connect disabled'} · presence only until you explicitly share records</span></div><button class="btn" data-open-collab>Room controls</button></div></section><section class="card span12"><h2>Ten systems, one outcome layer</h2><p class="muted">Choose a system for specialized tools or use the Nexus to design projects that cross institutional and disciplinary boundaries.</p>${domainCards()}</section><div class="grid" style="margin-top:14px"><section class="card span6"><h2>Unified collaboration stack</h2><div class="module-list">${['Projects + tasks + comments','Questions + handoffs','Decision records','Evidence ledger','Peer snapshot sync','Trystero 0.25.3 / WebRTC','Nostr / MQTT / Torrent / IPFS','BroadcastChannel fallback','Optional TURN','Legacy WebSocket adapter','WebLLM worker','PWA + offline shell','JSON portability'].map(x=>`<div class="module">${x}</div>`).join('')}</div></section><section class="card span6"><h2>Integrity boundaries</h2><p class="callout">Offline capability applies to the app shell and locally stored records after an HTTPS/localhost first load. Live agency data, external maps, peer discovery and uncached AI model artifacts require connectivity.</p><p class="callout warning">Public/P2P collaboration is not a protected-record system. Peer IDs and role labels are not verified human or institutional identities. Keep student PII, medical records, credentials, claim numbers, home addresses and secrets out of shared rooms.</p></section></div>`}

const DOMAIN_LINKS={
  food:['water','energy','mobility','connectivity','resilience','health'],
  water:['energy','food','health','housing','resilience','connectivity'],
  energy:['water','health','housing','connectivity','mobility','food','resilience'],
  housing:['insurance','energy','water','mobility','health','learning','connectivity','resilience'],
  resilience:['energy','water','food','health','mobility','connectivity','housing','insurance'],
  health:['mobility','connectivity','energy','water','food','housing','resilience'],
  insurance:['housing','resilience','energy','water'],
  mobility:['energy','housing','health','food','learning','connectivity','resilience'],
  learning:['connectivity','mobility','housing','health','food','energy'],
  connectivity:['learning','health','energy','water','mobility','food','resilience']
};
const LEVELS=[
  {name:'Observer',min:0},{name:'Connector',min:100},{name:'Systems Weaver',min:250},{name:'Steward',min:500},{name:'Commons Builder',min:900},{name:'Regenerative Architect',min:1400}
];
function contributionXP(){
  const r=state.records;
  let xp=0;
  xp+=r.projects.reduce((n,p)=>n+20+Math.min(15,(p.domains||[]).length*3),0);
  xp+=r.tasks.reduce((n,x)=>n+4+(/done|complete|closed/i.test(x.status||'')?10:0),0);
  xp+=Math.min(20,r.comments.length*2);
  xp+=r.evidence.length*12;
  xp+=r.decisions.length*10;
  xp+=r.questions.reduce((n,x)=>n+3+(/resolved|closed|answered/i.test(x.status||'')?7:0),0);
  xp+=r.handoffs.reduce((n,x)=>n+6+(/complete|accepted|done/i.test(x.status||'')?12:0),0);
  xp+=r.quests.reduce((n,x)=>n+(/complete|done/i.test(x.status||'')?Math.max(5,Math.min(200,Number(x.points)||25)):0),0);
  return xp;
}
function levelInfo(){const xp=contributionXP();let i=0;for(let n=0;n<LEVELS.length;n++)if(xp>=LEVELS[n].min)i=n;const cur=LEVELS[i],next=LEVELS[i+1];const pct=next?Math.max(0,Math.min(100,(xp-cur.min)/(next.min-cur.min)*100)):100;return {xp,cur,next,pct}}
function badges(){const r=state.records;const doneTasks=r.tasks.filter(x=>/done|complete|closed/i.test(x.status||'')).length;const doneHandoffs=r.handoffs.filter(x=>/complete|accepted|done/i.test(x.status||'')).length;const maxDomains=Math.max(0,...r.projects.map(p=>(p.domains||[]).length));return [
  {name:'First Bridge',ok:r.handoffs.length>0,why:'Create a cross-role handoff'},
  {name:'Evidence Keeper',ok:r.evidence.length>=5,why:'Record 5 evidence items'},
  {name:'System Weaver',ok:maxDomains>=5,why:'Build a 5+ domain project'},
  {name:'Closure Engine',ok:doneTasks>=10,why:'Complete 10 tasks'},
  {name:'Bridge Builder',ok:doneHandoffs>=3,why:'Complete 3 handoffs'},
  {name:'Decision Trail',ok:r.decisions.length>=5,why:'Record 5 decisions'}
]}
function collabHUD(){const l=levelInfo(),bs=badges();return `<section class="card span12"><div class="toolbar"><div style="margin-right:auto"><div class="eyebrow">Collaboration progression</div><h2 style="margin:.25rem 0">${esc(l.cur.name)} · ${l.xp} XP</h2></div><button class="btn" data-go="quests">Open Quest Board</button></div><div class="level-track" aria-label="Progress to next collaboration level"><span style="width:${l.pct.toFixed(1)}%"></span></div><p class="muted">${l.next?`${Math.max(0,l.next.min-l.xp)} XP to ${esc(l.next.name)}.`:'Highest current level reached.'} XP rewards completed work, evidence, decisions and accepted handoffs; comments are capped to reduce spam incentives.</p><div class="badge-row">${bs.map(b=>`<span class="badge ${b.ok?'':'locked'}" title="${esc(b.why)}">${b.ok?'◆':'◇'} ${esc(b.name)}</span>`).join('')}</div></section>`}
function projectCoverage(p){const ids=new Set(p.domains||[]),tasks=state.records.tasks.filter(x=>x.projectId===p.id),handoffs=state.records.handoffs.filter(x=>x.projectId===p.id);const evidence=state.records.evidence.filter(x=>ids.has(x.domain));const open=tasks.filter(x=>!/done|complete|closed/i.test(x.status||'')).length;return {domains:ids.size,tasks:tasks.length,open,handoffs:handoffs.length,evidence:evidence.length}}
function nexusRecommendations(domains,outcome){const picks=domains.map(id=>DOMAINS.find(d=>d.id===id)).filter(Boolean);const actions=[];for(const d of picks){const depth=DOMAIN_DEPTH[d.id]||{};actions.push({domain:d.id,title:`${d.label}: establish measurable baseline`,detail:(depth.measure||[d.playbook[0]])[0],kind:'task'});actions.push({domain:d.id,title:`${d.label}: select intervention`,detail:(depth.portfolio||d.playbook)[0],kind:'task'})}for(let i=0;i<picks.length;i++){for(const target of DOMAIN_LINKS[picks[i].id]||[]){if(domains.includes(target)&&picks[i].id<target){const td=DOMAINS.find(d=>d.id===target);actions.push({domain:'cross-domain',title:`Handoff: ${picks[i].label} ↔ ${td.label}`,detail:`Define the interface condition, owner, units/evidence, acceptance test and escalation path required for “${outcome||'the shared outcome'}”.`,kind:'handoff',from:picks[i].label,to:td.label})}}}return actions.slice(0,24)}
function renderNexus(){
  const seed=state.chainNexusSeed||{},seedDomains=new Set(seed.domains||[]);
  const rows=DOMAINS.map(d=>`<tr><td>${d.icon} <b>${esc(d.label)}</b></td><td>${esc(d.principle)}</td><td>${d.actors.slice(0,5).map(a=>`<span class="tag">${esc(a)}</span>`).join('')}</td></tr>`).join('');
  const projectOpts='<option value="">New / unlinked plan</option>'+state.records.projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');
  const roles=ROLE_CATALOG.map(r=>`<article class="role-card"><h3>${esc(r.label)}</h3><p><b>Contributes:</b> ${esc(r.contributes.join(' · '))}</p><p><b>Needs:</b> ${esc(r.needs.join(' · '))}</p><p class="muted"><b>Typical handoff:</b> ${esc(r.handoff)}</p></article>`).join('');
  const scans=state.records.projects.map(p=>{const c=projectCoverage(p);return `<article class="action-item"><strong>${esc(p.title)}</strong><span class="tag">${c.domains} domains</span><span class="tag">${c.tasks} tasks</span><span class="tag">${c.open} open</span><span class="tag">${c.evidence} evidence links</span><span class="tag">${c.handoffs} handoffs</span><p class="muted">${c.domains<3?'Potential blind spot: project is still narrow. ':''}${c.evidence===0?'Add evidence before major decisions. ':''}${c.open>0&&c.handoffs===0?'Convert blocked cross-team work into explicit handoffs.':''}</p></article>`}).join('');
  return breadcrumb('Cross-Domain Nexus')+hero('Dependency intelligence → executable work','Cross-Domain Nexus','Turn a shared outcome into explicit system dependencies, owners, evidence needs, interface contracts, tasks and handoffs across institutions and families.',`<button class="btn primary" data-go="projects">Project Commons</button><button class="btn" data-go="scenario">Open Cascade Lab</button><button class="btn" data-go="quests">Open Quest Board</button>`)+collabHUD()+`<div class="grid"><section class="card span12"><h2>Nexus Action Builder</h2><p class="muted">Select the systems that can enable or block the outcome. The builder generates measurable baseline tasks and cross-domain interface handoffs that can be saved directly into the shared coordination board.</p><form id="nexusForm" class="nexus-builder"><div class="field"><label>Outcome</label><input name="outcome" required maxlength="220" value="${esc(seed.outcome||'')}" placeholder="Maintain rural clinic service through a 72-hour outage"></div><div class="field"><label>Geography / service area</label><input name="geography" maxlength="180" value="${esc(seed.geography||'')}" placeholder="County, district or non-sensitive service area"></div><div class="field"><label>Link to project</label><select name="projectId">${projectOpts}</select></div><div class="field"><label>Decision / lead role</label><select name="role">${ROLE_CATALOG.map(r=>`<option value="${r.id}">${esc(r.label)}</option>`).join('')}</select></div><div class="field wide"><label>Domains</label><div class="domain-pick">${DOMAINS.map(d=>`<label><input type="checkbox" name="domains" value="${d.id}" ${seedDomains.has(d.id)?'checked':''}><span>${d.icon} ${esc(d.label)}</span></label>`).join('')}</div></div><div class="field wide"><label>Known constraint or failure mode</label><textarea name="constraint" placeholder="Budget ceiling, seasonal access, staffing, permitting, outage duration, data gap…"></textarea></div><div class="toolbar wide"><button class="btn primary">Generate executable dependency plan</button><button class="btn" type="button" data-go="status">Check current Texas status</button></div></form><div id="nexusResult" class="result">Choose an outcome and at least two domains.</div></section><section class="card span7"><h2>Project bottleneck scan</h2><div class="action-stack">${scans||'<p class="muted">Create a project to begin coverage scanning.</p>'}</div></section><section class="card span5"><h2>Interface contract</h2><ol class="steps"><li>Outcome + population</li><li>Input/output dependency</li><li>Units + threshold</li><li>Evidence + uncertainty</li><li>Authority / decision owner</li><li>Technical owner</li><li>Acceptance condition</li><li>Escalation + review trigger</li></ol></section><section class="card span12"><h2>Dependency matrix</h2><div class="table-wrap"><table><thead><tr><th>System</th><th>Operating principle</th><th>Typical collaborators</th></tr></thead><tbody>${rows}</tbody></table></div></section><section class="card span12"><h2>Institution-to-family collaboration roles</h2><div class="role-grid">${roles}</div></section></div>`
}

function renderStatus(){const grouped={};for(const x of STATUS_FACTS)(grouped[x.domain]??=[]).push(x);const blocks=Object.entries(grouped).map(([domain,items])=>{const d=DOMAINS.find(x=>x.id===domain);return `<section class="card span6"><div class="toolbar"><h2 style="margin-right:auto">${d?d.icon+' '+esc(d.label):'◎ Cross-domain'}</h2><span class="pill">${items.length} dated anchor${items.length===1?'':'s'}</span></div>${items.map(x=>`<article class="status-record"><div class="eyebrow">As of ${esc(x.asOf)} · ${esc(x.status)}</div><h3>${esc(x.title)}</h3><p>${esc(x.fact)}</p><p class="muted"><b>Limitation:</b> ${esc(x.limits)}</p><a class="btn" href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">${esc(x.source)} ↗</a></article>`).join('')}</section>`}).join('');return breadcrumb('Texas Status & Evidence')+hero('Dated facts, not timeless assumptions','Texas Status & Evidence','A current-state layer for statewide programs and data sources. Every status item carries an as-of date, primary source and limitation so teams can distinguish planning context from local reality.',`<button class="btn" data-go="evidence">Open evidence ledger</button>`)+`<div class="grid">${blocks}</div>`}

function domainByRoute(){return DOMAINS.find(d=>'domain-'+d.id===state.route)}
function calculator(d){const k=d.calc.kind;const defs={
food:[['people','People','number',4],['days','Days of reserve','number',7],['cal','Calories/person/day','number',2200],['margin','Contingency %','number',15]],
water:[['roof','Roof area (ft²)','number',1600],['rain','Rainfall event (in)','number',1],['eff','Capture efficiency %','number',80]],
energy:[['battery','Usable battery (kWh)','number',10],['load','Critical load (kW)','number',0.8],['eff','System efficiency %','number',88]],
housing:[['shelter','Rent/mortgage','number',1800],['tax','Property tax / fees','number',350],['ins','Insurance','number',220],['util','Utilities','number',280],['maint','Maintenance reserve','number',180],['transport','Transport','number',650],['income','Gross monthly income','number',6500]],
resilience:[['water','Water plan 0–5','number',3],['power','Power backup 0–5','number',2],['comms','Communication backup 0–5','number',2],['evac','Evacuation/shelter 0–5','number',3],['med','Medication/health continuity 0–5','number',2],['docs','Documents/insurance 0–5','number',3]],
health:[['travel','Travel barrier 0–5','number',2],['cost','Cost barrier 0–5','number',2],['schedule','Scheduling barrier 0–5','number',2],['language','Language/accessibility barrier 0–5','number',0],['connect','Connectivity barrier 0–5','number',1]],
insurance:[['loss','Estimated loss ($)','number',50000],['coverage','Applicable coverage limit ($)','number',45000],['deductible','Deductible ($)','number',5000],['savings','Liquid recovery savings ($)','number',4000]],
mobility:[['monthly','Monthly transport spend ($)','number',900],['income','Gross monthly income ($)','number',6000],['minutes','Daily travel minutes','number',80],['days','Travel days/month','number',22]],
learning:[['positions','Teacher positions','number',100],['vacancies','Current vacancies','number',8],['hires','Expected hires','number',7],['exits','Expected exits','number',9]],
connectivity:[['access','Availability barrier 0–5','number',2],['afford','Affordability barrier 0–5','number',3],['device','Device barrier 0–5','number',1],['skills','Skills barrier 0–5','number',1],['reliability','Reliability barrier 0–5','number',3]]};
return `<section class="card span6"><h2>${esc(d.calc.title)}</h2><p class="muted">${esc(d.calc.desc)}</p><form class="calc-form" data-kind="${k}"><div class="form-grid">${defs[k].map(([id,l,t,v])=>`<div class="field"><label for="${k}_${id}">${esc(l)}</label><input id="${k}_${id}" name="${id}" type="${t}" step="any" value="${v}" ${l.includes('0–5')?'min="0" max="5"':l.includes('%')?'min="0" max="100"':'min="0"'}></div>`).join('')}</div><button class="btn primary" style="margin-top:12px">Calculate</button><div class="result" data-result>Enter values and calculate.</div></form></section>`}
function calcResult(kind,f){const n=x=>Math.max(0,Number(f.get(x)||0));if(kind==='food'){const base=n('people')*n('days')*n('cal');const total=base*(1+n('margin')/100);return `${Math.round(total).toLocaleString()} kcal target (${Math.round(base).toLocaleString()} base + contingency). Build a nutritionally diverse reserve; calories alone do not establish a complete diet.`}if(kind==='water'){const gal=n('roof')*n('rain')*0.623*(n('eff')/100);return `${gal.toFixed(0)} gallons theoretical captured yield. Storage, first-flush diversion, water quality and local rules determine usable supply.`}if(kind==='energy'){const hrs=n('load')>0?(n('battery')*n('eff')/100)/n('load'):0;return `${hrs.toFixed(1)} hours estimated runtime at the entered steady load. Surge loads and battery protection limits can reduce actual runtime.`}if(kind==='housing'){const total=n('shelter')+n('tax')+n('ins')+n('util')+n('maint')+n('transport');const share=n('income')?total/n('income')*100:0;return `$${total.toFixed(0)}/month combined burden, about ${share.toFixed(1)}% of entered gross income. This is not a lending or eligibility determination.`}if(kind==='resilience'){const vals=['water','power','comms','evac','med','docs'].map(n);const pct=vals.reduce((a,b)=>a+b,0)/30*100;return `${pct.toFixed(0)}% preparedness coverage on this six-factor self-check. Treat low-scoring factors as planning prompts, not predictions.`}if(kind==='health'){const vals=['travel','cost','schedule','language','connect'].map(n);const sum=vals.reduce((a,b)=>a+b,0);return `Access-friction score ${sum}/25. Highest entered barriers should shape navigation and support planning; this score has no diagnostic meaning.`}if(kind==='insurance'){const insurance=Math.max(0,n('coverage')-n('deductible'));const gap=Math.max(0,n('loss')-insurance-n('savings'));return `Scenario resources: $${(insurance+n('savings')).toLocaleString()}; estimated uncovered gap: $${gap.toLocaleString()}. Actual coverage depends on policy terms, exclusions, valuation and claim facts.`}if(kind==='mobility'){const share=n('income')?n('monthly')/n('income')*100:0;const hours=n('minutes')*n('days')/60;return `${share.toFixed(1)}% of gross monthly income plus ~${hours.toFixed(1)} travel hours/month. Use this alongside safety, reliability and accessibility—not as a standalone ranking.`}if(kind==='learning'){const next=Math.min(n('positions'),Math.max(0,n('vacancies')+n('exits')-n('hires')));const filled=Math.max(0,n('positions')-next);return `Simplified next-period vacancies: ${next}; filled positions: ${filled}/${n('positions')}. Real staffing depends on subject, location, certification, enrollment and budget.`}if(kind==='connectivity'){const m={access:n('access'),afford:n('afford'),device:n('device'),skills:n('skills'),reliability:n('reliability')};const top=Object.entries(m).sort((a,b)=>b[1]-a[1])[0];return `Highest entered barrier: ${top[0]} (${top[1]}/5). Address the barrier mix rather than assuming infrastructure deployment alone solves digital opportunity.`}return 'No result'}
function renderDomain(d){const depth=DOMAIN_DEPTH[d.id]||{measure:[],portfolio:[],handoffs:[],failures:[]};const list=x=>`<ul>${x.map(v=>`<li>${esc(v)}</li>`).join('')}</ul>`;return breadcrumb(d.label)+hero('Specialized system',d.label,d.mission,`<button class="btn primary" data-go="projects">Start ${esc(d.label)} project</button><button class="btn" data-go="coordination">Open coordination board</button><button class="btn" data-go="evidence">Open evidence</button>`)+`<div class="grid"><section class="card span6"><h2>Operating principle</h2><p class="callout">${esc(d.principle)}</p><h3>Core collaborators</h3>${d.actors.map(a=>`<span class="tag">${esc(a)}</span>`).join('')}<h3 style="margin-top:18px">Action sequence</h3><ol class="steps">${d.playbook.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></section>${calculator(d)}<section class="card span6"><h2>What to measure</h2>${list(depth.measure)}</section><section class="card span6"><h2>Intervention portfolio</h2>${list(depth.portfolio)}</section><section class="card span6"><h2>Cross-domain handoffs</h2>${list(depth.handoffs)}</section><section class="card span6"><h2>Failure modes to test</h2>${list(depth.failures)}</section><section class="card span12"><h2>${d.modules.length} integrated modules</h2><p class="muted">Use these as a completeness checklist, then ground each selected module in local evidence, ownership and measurable outcomes.</p><div class="module-list">${d.modules.map(m=>`<div class="module"><b>${esc(m)}</b><br><small class="muted">Assess → evidence → intervention → owner → metric → review</small></div>`).join('')}</div></section><section class="card span12"><h2>Current Texas status anchors</h2>${STATUS_FACTS.filter(e=>e.domain===d.id).map(e=>`<article class="status-record"><div class="eyebrow">As of ${esc(e.asOf)} · ${esc(e.status)}</div><h3>${esc(e.title)}</h3><p>${esc(e.fact)}</p><p class="muted"><b>Limitation:</b> ${esc(e.limits)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.source)} ↗</a></article>`).join('')||'<p class="muted">No dated statewide status record is bundled for this domain; use the Evidence Ledger and current local sources.</p>'}</section><section class="card span12"><h2>Evidence anchors</h2>${EVIDENCE.filter(e=>e.domain===d.id).map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer"><b>${esc(e.title)}</b></a><br><span class="muted">Retrieved ${esc(e.date)} · ${esc(e.note)}</span></p>`).join('')||'<p class="muted">Use the central evidence ledger to add verified local and official sources for this domain.</p>'}</section></div>`}

function projectForm(){return `<form id="projectForm"><div class="form-grid"><div class="field"><label>Project title</label><input name="title" required maxlength="120" placeholder="e.g., Rural clinic continuity upgrade"></div><div class="field"><label>Lead organization / team</label><input name="owner" maxlength="120" placeholder="Team or institution"></div><div class="field"><label>Geography / service area</label><input name="geography" maxlength="180" placeholder="County, region, district or non-sensitive area"></div><div class="field"><label>Primary outcome</label><input name="outcome" required maxlength="220" placeholder="Measurable outcome"></div><div class="field"><label>Stage</label><select name="stage"><option>Discovery</option><option>Design</option><option>Funding</option><option>Implementation</option><option>Operations</option><option>Evaluation</option></select></div><div class="field"><label>Information class</label><select name="privacy"><option>Public coordination</option><option>Internal non-sensitive</option><option>Do not share P2P</option></select></div></div><div class="field" style="margin-top:12px"><label>Domains</label><div>${DOMAINS.map(d=>`<label class="tag"><input type="checkbox" name="domains" value="${d.id}"> ${d.icon} ${esc(d.label)}</label>`).join('')}</div></div><div class="field" style="margin-top:12px"><label>Participating roles / organizations</label><textarea name="participants" placeholder="Families; county; school district; utility; university; employer; nonprofit…"></textarea></div><div class="field" style="margin-top:12px"><label>Dependencies / assumptions</label><textarea name="dependencies" placeholder="What must be true for this project to work?"></textarea></div><div class="field" style="margin-top:12px"><label>Success metrics / acceptance conditions</label><textarea name="metrics" placeholder="How will the team know the intervention worked?"></textarea></div><button class="btn primary" style="margin-top:12px">Save project</button></form>`}
function renderProjects(){const cards=state.records.projects.map(p=>`<article class="card span6"><div class="toolbar"><h3 style="margin-right:auto">${esc(p.title)}</h3><span class="pill">${esc(p.stage)}</span></div><p>${esc(p.outcome)}</p><p>${(p.domains||[]).map(id=>{const d=DOMAINS.find(x=>x.id===id);return d?`<span class="tag">${d.icon} ${esc(d.label)}</span>`:''}).join('')}</p><p><b>Participants:</b> ${esc(p.participants||'not recorded')}</p><p><b>Success:</b> ${esc(p.metrics||'not recorded')}</p><p class="muted">Lead: ${esc(p.owner||'Unassigned')} · ${esc(p.geography||'geography not set')} · ${esc(p.privacy||'Public coordination')} · rev ${p.rev||1}</p><div class="toolbar"><button class="btn" data-share-record="projects" data-id="${p.id}" ${p.privacy==='Do not share P2P'?'disabled title="Marked do not share P2P"':''}>Share to room</button><button class="btn" data-delete="projects" data-id="${p.id}">Delete</button></div></article>`).join('');return breadcrumb('Project Commons')+hero('Local-first multidisciplinary work','Project Commons','Create projects that explicitly cross domains and organizations, preserve assumptions, metrics and information-class boundaries, then share only non-sensitive records to connected peers.',`<button class="btn" data-export>Export backup</button>`)+`<div class="grid"><section class="card span12"><h2>New project</h2>${projectForm()}</section>${cards||'<section class="card span12 empty">No projects yet.</section>'}</div>`}
function renderCoordination(){
  const projects=state.records.projects;
  const projectOpts='<option value="">No project / general</option>'+projects.map(p=>`<option value="${p.id}">${esc(p.title)}</option>`).join('');
  const domainOpts='<option value="cross-domain">Cross-domain</option>'+DOMAINS.map(d=>`<option value="${d.id}">${esc(d.label)}</option>`).join('');
  const roleOpts=ROLE_CATALOG.map(r=>`<option value="${r.id}">${esc(r.label)}</option>`).join('');
  const taskCards=state.records.tasks.map(x=>`<article class="card"><div class="toolbar"><h3 style="margin-right:auto">${esc(x.title)}</h3><span class="pill">${esc(x.status||'Open')}</span></div><p class="muted">Owner: ${esc(x.owner||'Unassigned')} · Role: ${esc(x.role||'not set')} · Due: ${esc(x.due||'not set')} · ${esc(x.domain||'cross-domain')}</p><p>${esc(x.detail||'')}</p><div class="toolbar"><button class="btn" data-record-status="tasks" data-id="${x.id}" data-status="${/done|complete|closed/i.test(x.status||'')?'Open':'Done'}">${/done|complete|closed/i.test(x.status||'')?'Reopen':'Mark done'}</button><button class="btn" data-share-record="tasks" data-id="${x.id}">Share</button><button class="btn" data-delete="tasks" data-id="${x.id}">Delete</button></div></article>`).join('');
  const commentCards=state.records.comments.map(x=>`<article class="card"><div class="toolbar"><h3 style="margin-right:auto">Comment</h3><span class="pill">${esc(x.role||'contributor')}</span></div><p>${esc(x.body||'')}</p><p class="muted">Project: ${esc(projectTitle(x.projectId))} · ${esc(x.author||'Anonymous role')} · ${esc(x.updatedAt||'')}</p><div class="toolbar"><button class="btn" data-share-record="comments" data-id="${x.id}">Share</button><button class="btn" data-delete="comments" data-id="${x.id}">Delete</button></div></article>`).join('');
  const qCards=state.records.questions.map(x=>`<article class="card"><div class="toolbar"><h3 style="margin-right:auto">${esc(x.title)}</h3><span class="pill">${esc(x.status||'Open')}</span></div><p class="muted">Owner: ${esc(x.owner||'Unassigned')} · ${esc(x.domain||'cross-domain')}</p><div class="toolbar"><button class="btn" data-record-status="questions" data-id="${x.id}" data-status="${/resolved|closed|answered/i.test(x.status||'')?'Open':'Resolved'}">${/resolved|closed|answered/i.test(x.status||'')?'Reopen':'Resolve'}</button><button class="btn" data-share-record="questions" data-id="${x.id}">Share</button><button class="btn" data-delete="questions" data-id="${x.id}">Delete</button></div></article>`).join('');
  const hCards=state.records.handoffs.map(x=>`<article class="card"><div class="toolbar"><h3 style="margin-right:auto">${esc(x.title)}</h3><span class="pill">${esc(x.status||'Pending')}</span></div><p><b>${esc(x.from||'Unassigned')}</b> → <b>${esc(x.to||'Unassigned')}</b></p><p>${esc(x.condition||'')}</p><div class="toolbar"><button class="btn" data-record-status="handoffs" data-id="${x.id}" data-status="${/complete|accepted|done/i.test(x.status||'')?'Pending':'Accepted'}">${/complete|accepted|done/i.test(x.status||'')?'Reopen':'Accept handoff'}</button><button class="btn" data-share-record="handoffs" data-id="${x.id}">Share</button><button class="btn" data-delete="handoffs" data-id="${x.id}">Delete</button></div></article>`).join('');
  return breadcrumb('Coordination Board')+hero('From discussion to accountable handoffs','Coordination Board','Tasks, comments, open questions and handoffs connect disciplines without collapsing their responsibilities. Records remain local until explicitly shared or included in a room snapshot.')+`<div class="grid">
  <section class="card span12"><h2>New task</h2><form id="taskForm"><div class="form-grid"><div class="field"><label>Task</label><input name="title" required maxlength="180"></div><div class="field"><label>Project</label><select name="projectId">${projectOpts}</select></div><div class="field"><label>Owner</label><input name="owner" maxlength="120"></div><div class="field"><label>Disciplinary / stakeholder role</label><select name="role">${roleOpts}</select></div><div class="field"><label>Due date</label><input type="date" name="due"></div><div class="field"><label>Domain</label><select name="domain">${domainOpts}</select></div><div class="field"><label>Status</label><select name="status"><option>Open</option><option>In progress</option><option>Blocked</option><option>Done</option></select></div></div><div class="field" style="margin-top:10px"><label>Detail / acceptance condition</label><textarea name="detail"></textarea></div><button class="btn primary" style="margin-top:10px">Save task</button></form></section>
  <section class="card span6"><h2>Project comment</h2><form id="commentForm"><div class="field"><label>Project</label><select name="projectId">${projectOpts}</select></div><div class="form-grid"><div class="field"><label>Role</label><select name="role">${roleOpts}</select></div><div class="field"><label>Author / team label</label><input name="author" maxlength="120" placeholder="Non-sensitive label"></div></div><div class="field"><label>Comment</label><textarea name="body" required maxlength="4000"></textarea></div><button class="btn primary" style="margin-top:10px">Save comment</button></form></section>
  <section class="card span6"><h2>Open question</h2><form id="questionForm"><div class="field"><label>Question</label><textarea name="title" required></textarea></div><div class="form-grid"><div class="field"><label>Owner</label><input name="owner"></div><div class="field"><label>Domain</label><select name="domain">${domainOpts}</select></div></div><input type="hidden" name="status" value="Open"><button class="btn primary" style="margin-top:10px">Record question</button></form></section>
  <section class="card span12"><h2>Handoff</h2><form id="handoffForm"><div class="form-grid"><div class="field"><label>Handoff / deliverable</label><input name="title" required></div><div class="field"><label>Project</label><select name="projectId">${projectOpts}</select></div><div class="field"><label>From</label><input name="from"></div><div class="field"><label>To</label><input name="to"></div></div><div class="field"><label>Acceptance / trigger condition</label><textarea name="condition"></textarea></div><input type="hidden" name="status" value="Pending"><button class="btn primary" style="margin-top:10px">Record handoff</button></form></section>
  ${taskCards||'<section class="card span12 empty">No tasks yet.</section>'}${commentCards}${qCards}${hCards}</div>`;
}
function projectTitle(id){return state.records.projects.find(p=>p.id===id)?.title||'General'}
function renderEvidence(){const local=state.records.evidence.map(e=>`<tr><td>${esc(e.domain)}</td><td><b>${esc(e.title)}</b><br><span class="muted">${esc(e.note||'')}</span></td><td>${esc(e.date||'')}</td><td>${e.url?`<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Open</a>`:''}</td><td><button class="btn" data-delete="evidence" data-id="${e.id}">Delete</button></td></tr>`).join('');const official=EVIDENCE.map(e=>`<tr><td>${esc(e.domain)}</td><td><b>${esc(e.title)}</b><br><span class="muted">${esc(e.note)}</span></td><td>${esc(e.date)}</td><td><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">Official source</a></td><td><span class="pill">bundled</span></td></tr>`).join('');return breadcrumb('Evidence Ledger')+hero('Provenance before persuasion','Evidence Ledger','Track source, date, scope and limitations. Bundled entries are reference anchors; add local evidence without overwriting the original source context.')+`<div class="grid"><section class="card span12"><form id="evidenceForm"><div class="form-grid"><div class="field"><label>Domain</label><select name="domain">${DOMAINS.map(d=>`<option value="${d.id}">${esc(d.label)}</option>`).join('')}</select></div><div class="field"><label>Source date / retrieval date</label><input type="date" name="date" value="${SNAPSHOT}"></div><div class="field"><label>Title</label><input name="title" required maxlength="180"></div><div class="field"><label>URL</label><input name="url" type="url" placeholder="https://…"></div></div><div class="field" style="margin-top:10px"><label>Scope / limitation note</label><textarea name="note"></textarea></div><button class="btn primary" style="margin-top:10px">Add evidence</button></form></section><section class="card span12"><div class="table-wrap"><table><thead><tr><th>Domain</th><th>Evidence</th><th>Date</th><th>Source</th><th>Status</th></tr></thead><tbody>${local}${official}</tbody></table></div></section></div>`}
function renderDecisions(){const items=state.records.decisions.map(d=>`<article class="card span6"><h3>${esc(d.title)}</h3><p>${esc(d.rationale)}</p><p class="muted">Owner: ${esc(d.owner||'Unassigned')} · Review: ${esc(d.review||'not set')}</p><button class="btn" data-delete="decisions" data-id="${d.id}">Delete</button></article>`).join('');return breadcrumb('Decision Records')+hero('Accountable decisions','Decision Records','Record what was decided, why, by whom, and when it should be reviewed. Keep uncertainty and authority boundaries visible.')+`<div class="grid"><section class="card span12"><form id="decisionForm"><div class="form-grid"><div class="field"><label>Decision</label><input name="title" required maxlength="180"></div><div class="field"><label>Owner / authority</label><input name="owner" maxlength="120"></div><div class="field"><label>Review date</label><input name="review" type="date"></div><div class="field"><label>Status</label><select name="status"><option>Proposed</option><option>Accepted</option><option>Implemented</option><option>Superseded</option></select></div></div><div class="field" style="margin-top:10px"><label>Rationale, evidence and uncertainty</label><textarea name="rationale" required></textarea></div><button class="btn primary" style="margin-top:10px">Save decision</button></form></section>${items||'<section class="card span12 empty">No decisions recorded yet.</section>'}</div>`}
function renderScenario(){const seed=state.chainScenarioSeed||{},seedDomains=new Set(seed.domains||[]);return breadcrumb('Cascade Lab')+hero('Stress test → propagation → action plan','Cross-Domain Cascade Lab','Explore how disruption can propagate through connected systems, then convert the transparent scenario into tasks, handoffs and a resilience quest. It remains a planning heuristic—not a forecast or probability model.',`<button class="btn" data-go="nexus">Open Nexus</button><button class="btn" data-go="quests">Quest Board</button>`)+`<div class="grid"><section class="card span6"><h2>Scenario inputs</h2><form id="scenarioForm"><div class="form-grid"><div class="field"><label>Duration</label><select name="duration"><option value="1">Hours / short disruption</option><option value="1.15">1–3 days</option><option value="1.3">Multi-day / extended</option></select></div><div class="field"><label>Readiness / mitigation</label><select name="readiness"><option value="0">Low / unknown</option><option value="0.15">Some redundancy</option><option value="0.3">Strong plans + redundancy</option><option value="0.4">High readiness</option></select></div><div class="field"><label>Service area</label><input name="geography" maxlength="180" value="${esc(seed.geography||'')}" placeholder="Non-sensitive county / district / facility type"></div><div class="field"><label>Critical outcome</label><input name="outcome" maxlength="220" value="${esc(seed.outcome||'')}" placeholder="Maintain essential clinic operations"></div></div>${DOMAINS.map(d=>`<div class="field" style="margin:8px 0"><label>${d.icon} ${esc(d.label)} <output id="out_${d.id}">${seedDomains.has(d.id)?1:0}</output>/5</label><input type="range" min="0" max="5" value="${seedDomains.has(d.id)?1:0}" name="${d.id}" oninput="document.getElementById('out_${d.id}').value=this.value"></div>`).join('')}<button class="btn primary" style="margin-top:12px">Run cascade + action analysis</button></form></section><section class="card span6"><h2>Propagation & priorities</h2><div id="scenarioResult" class="result">Increase one or more stressors, then run the scenario.</div><p class="muted">The algorithm exposes its assumptions: direct entered stress propagates through a fixed dependency graph, duration amplifies it, and readiness reduces it. No probabilities are calculated.</p></section><section class="card span12"><h2>Action conversion</h2><div id="scenarioActions" class="result">Run a scenario to generate intervention tasks, evidence questions and handoffs.</div></section></div>`}


function renderGuides(){return breadcrumb('Advanced Guides')+hero('Progressive depth','Simplified Advanced Guides','Each guide moves from a one-minute explanation to action steps, advanced framing and expert implementation detail.')+GUIDES.map(g=>`<details class="guide"><summary>${esc(g.title)}</summary><div class="guide-body"><div class="guide-level"><b>One minute</b><p>${esc(g.one)}</p></div><div class="guide-level"><b>Actionable steps</b><ol>${g.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div><div class="guide-level"><b>Advanced</b><p>${esc(g.advanced)}</p></div><div class="guide-level"><b>Expert / implementation</b><p>${esc(g.expert)}</p></div></div></details>`).join('')}
function renderAI(){return breadcrumb('Local AI Lab')+hero('Local-first AI + public hosted synthesis','Local AI Studio — Public Intelligence Router Edition','This edition layers hardware-aware WebLLM, service-worker model staging, local offline model packs, optional localhost 8B+ inference, an opportunistic public Cloudflare inference gateway, and a deterministic zero-dependency fallback. Hosted inference is an accelerator, never a hard dependency.')+`<div class="grid">
<section class="card span12"><div class="toolbar"><div><h2 style="margin-bottom:.25rem">Hardware autodetect, runtime & storage readiness</h2><p class="muted" style="margin:0">The browser cannot reliably expose exact GPU VRAM, so the detector uses reported WebGPU features/limits, system-memory hints, CPU concurrency and storage to build a conservative hardware profile. Model compatibility still comes from each model’s declared WebGPU requirements.</p></div><button class="btn primary" id="autoDetectAI">Autodetect hardware & recommend</button><button class="btn" id="refreshAIEnv">Refresh</button><button class="btn" id="persistAIStorage">Request persistent storage</button><button class="btn" id="testAIHosts">Test model hosts</button></div><div id="aiEnvironment" class="team-pulse" style="margin-top:12px"><div class="pulse-cell"><span>WebGPU</span><strong>Checking…</strong></div></div><div id="aiRecommendations" class="ai-recommendations" style="margin-top:12px"><div class="result">Autodetecting local hardware and compatible models…</div></div><div id="aiHostProbe" class="result" style="margin-top:12px">Host test not run. Select/load the catalog, then test the selected model’s runtime, Hugging Face config and compiled WebGPU library paths.</div></section>
${window.TXAIDeployment?.render?.()||''}${window.TXPublicInference?.render?.()||''}<section class="card span12"><div class="toolbar"><div><h2 style="margin-bottom:.25rem">AI Resilience & Offline Model Packs</h2><p class="muted" style="margin:0">Stage model artifacts into a dedicated PWA cache before inference, or import a model pack from disk when browser access to model hosts is unreliable. Cached assets are served back to WebLLM by the service worker using their original URLs.</p></div><button class="btn primary" id="stageAIModel">Stage selected model for offline</button><button class="btn" id="installHostedAIPack">Install hosted offline pack</button><button class="btn" id="verifyAIStage">Verify staged assets</button><button class="btn" id="clearAIStage">Clear staged assets</button></div><div id="aiResilienceStatus" class="result" style="margin-top:12px">PWA model staging has not run yet.</div><div class="progress" style="margin-top:10px"><span id="aiStageProgress"></span></div><div class="form-grid" style="margin-top:12px"><div class="field"><label>Install offline model pack from folder</label><label class="btn">Choose model-pack folder<input id="aiPackFolder" type="file" webkitdirectory directory multiple hidden></label><small class="muted">Folder should include mlc-chat-config.json, ndarray-cache.json, tokenizer files, parameter shards, and the selected model library as its original filename or model_lib.wasm. An optional webllm-0.2.85.mjs installs the runtime locally too.</small></div><div class="field"><label>Recovery order</label><div class="callout"><b>1.</b> Local PWA runtime/cache → <b>2.</b> public hosted gateway for hard synthesis when configured → <b>3.</b> remote WebLLM/model hosts → <b>4.</b> optional localhost/remote endpoint → <b>5.</b> deterministic planner.</div></div></div><details class="guide" style="margin-top:12px"><summary>Local / optional remote OpenAI-compatible endpoint</summary><div class="guide-body"><p class="muted">Use a local inference server only if you run one. Credentials are kept in the form and are not persisted by this app.</p><div class="form-grid"><div class="field"><label for="aiEndpointBase">Base URL</label><input id="aiEndpointBase" placeholder="http://localhost:1234/v1"></div><div class="field"><label for="aiEndpointModel">Model name</label><input id="aiEndpointModel" placeholder="local model name"></div><div class="field"><label for="aiEndpointKey">API key (optional/session only)</label><input id="aiEndpointKey" type="password" autocomplete="off"></div><div class="field"><label>&nbsp;</label><button class="btn" id="testAIEndpoint">Test endpoint</button></div></div><div id="aiEndpointStatus" class="result">Endpoint not configured.</div></div></details></section>
<section class="card span12"><div class="toolbar"><div><h2 style="margin-bottom:.25rem">Model library</h2><p class="muted" style="margin:0">Models come from <code>webllm.prebuiltAppConfig.model_list</code>. Compute tiers and individual models are collapsible to keep the page compact.</p></div><button class="btn primary" id="loadModelCatalog">Load compatible catalog</button></div><div class="form-grid" style="margin-top:12px"><div class="field"><label for="aiBackend">Cache backend</label><select id="aiBackend"><option value="cache">Cache API — direct-engine default</option><option value="indexeddb">IndexedDB</option><option value="opfs">OPFS</option></select></div><div class="field"><label for="aiStrategy">Engine strategy <span class="tooltip" tabindex="0" data-tip="Direct engine uses CreateMLCEngine on the page. Worker mode uses CreateWebWorkerMLCEngine. Both ultimately require the same model artifacts, so a blocked model host can affect both.">?</span></label><select id="aiStrategy"><option value="direct-worker">Direct engine → worker fallback</option><option value="direct-only">Direct engine only</option><option value="worker-only">Worker only (comparison)</option></select></div><div class="field"><label for="aiTier">Compute tier</label><select id="aiTier"><option value="all">All compute tiers</option><option value="tiny">Tiny / ≤1.2 GB VRAM</option><option value="light">Light / 1.2–2.5 GB</option><option value="medium">Medium / 2.5–4.5 GB</option><option value="heavy">Heavy / 4.5–7 GB</option><option value="extreme">Extreme / &gt;7 GB</option><option value="unknown">Unknown requirement</option></select></div><div class="field"><label for="aiCompat">Device compatibility</label><select id="aiCompat"><option value="compatible">Compatible only — recommended</option><option value="all">All models</option><option value="incompatible">Incompatible only</option></select></div><div class="field"><label for="aiModelSearch">Filter models</label><input id="aiModelSearch" placeholder="Llama, Qwen, Phi, Gemma, Mistral…"></div><div class="field"><label for="aiModelSort">Sort within tiers</label><select id="aiModelSort"><option value="vram-asc">Compute: lowest first</option><option value="vram-desc">Compute: highest first</option><option value="name">Name</option></select></div></div><div id="aiCatalogStatus" class="result" style="margin-top:12px">Catalog not loaded. Loading it downloads the WebLLM JavaScript runtime, not model weights.</div><div id="aiModelCatalog" class="model-catalog compact" style="margin-top:12px"></div></section>
<section class="card span6"><h2>Active model</h2><div id="aiStatus" class="result">No model loaded.</div><p class="callout warning"><b>Hardware-aware default:</b> the lightest compatible model is selected automatically after autodetection. This is the safest starting point; larger recommendations are optional and remain heuristic because browsers do not expose dependable GPU-VRAM totals.</p><div class="toolbar" style="margin-top:10px"><button class="btn primary" id="loadAI" disabled>Load selected model</button><button class="btn" id="downloadAI" disabled>Download & cache</button><button class="btn" id="unloadAI" disabled>Unload GPU model</button></div><p class="muted">This edition tries <code>CreateMLCEngine</code> first. If the selected strategy permits it, the dedicated worker is a fallback. A true network block to Hugging Face or the model-library host is shared by both paths.</p><details class="guide" id="aiDiagnostics" style="margin-top:12px"><summary>Download diagnostics</summary><div class="guide-body"><div id="aiDiagBody" class="guide-level">No download attempt yet. Failed attempts will show the stage, engine path, likely cause and raw error here.</div><div class="toolbar"><button class="btn" id="retryAISafe" disabled>Retry Cache API + direct engine</button><button class="btn" id="copyAIDiag" disabled>Copy diagnostics</button></div></div></details></section>
<section class="card span6"><h2>Adaptive planning prompt</h2><div class="field"><label for="aiPrompt">Planning request</label><textarea id="aiPrompt" placeholder="Generate a comprehensive edible infrastructure plan for northern Texas, including site types, implementation phases, water/soil strategy, governance, maintenance, metrics and cross-domain collaboration."></textarea></div><div id="aiTaskAssessment" class="result" style="margin-top:10px">Type a request to see task complexity, recommended model class and generation strategy.</div><div class="form-grid" style="margin-top:10px"><div class="field"><label for="aiPlanningMode">Planning depth</label><select id="aiPlanningMode"><option value="auto">Auto-detect</option><option value="fast">Fast / concise</option><option value="comprehensive">Comprehensive</option><option value="expert">Expert implementation</option></select></div><div class="field"><label><input id="aiAutoEscalate" type="checkbox" checked> Auto-switch to a stronger cached compatible model when useful</label></div><div class="field"><label><input id="aiUseScaffold" type="checkbox" checked> Use deterministic planning scaffold</label></div><div class="field"><label for="aiTemperature">Temperature</label><input id="aiTemperature" type="number" min="0" max="1.5" step="0.1" value="0.25"></div><div class="field"><label for="aiMaxTokens">Max output tokens</label><input id="aiMaxTokens" type="number" min="64" max="2048" step="64" value="1600"></div></div><div class="toolbar" style="margin-top:10px"><button class="btn primary" id="runResilientAI">Run adaptive planner</button><button class="btn" id="runAI" disabled>Generate with current model</button><button class="btn" id="runFallback">Run deterministic planner</button></div><p class="muted">For complex requests, the app now separates <b>compatibility default</b> from <b>task-quality recommendation</b>. The lightest model still starts first, but comprehensive work is scaffolded and can escalate to a stronger cached model.</p><div id="aiOutput" class="result">Output will appear here.</div></section>
<section class="card span12"><details class="guide"><summary>Compute-tier guide</summary><div class="guide-body"><div class="role-grid"><div class="role-card"><b>Tiny</b><p>≤1.2 GB declared VRAM. Best first test for constrained hardware.</p></div><div class="role-card"><b>Light</b><p>1.2–2.5 GB. Practical for many modern laptops.</p></div><div class="role-card"><b>Medium</b><p>2.5–4.5 GB. Needs materially stronger GPU resources.</p></div><div class="role-card"><b>Heavy</b><p>4.5–7 GB. Desktop-class territory.</p></div><div class="role-card"><b>Extreme</b><p>&gt;7 GB. High-end hardware only unless tested.</p></div></div><p class="callout warning">Declared VRAM is not download size and does not guarantee successful allocation. The first model load still requires external model artifacts unless already cached.</p></div></details></section></div>`}
function renderAbout(){return breadcrumb('Architecture & Safety')+hero('Local-first, explicit boundaries','Architecture & Safety','The system combines PWA/offline storage, browser-local and localhost AI, peer collaboration, evidence provenance and executable Meta-Chains. It does not treat hashes as truth, peer labels as verified identity, or offline caches as a substitute for current authoritative data.')+`<div class="grid"><section class="card span6"><h2>AI execution boundaries</h2><p>The browser model tiers are optional local computation. Larger 8B+ models are intended for an explicitly configured localhost runtime. Remote endpoints remain opt-in.</p><p class="callout">No API key is embedded in this bundle. Endpoint secrets entered in the AI Lab are session-only.</p></section><section class="card span6"><h2>PWA boundary</h2><p>A service worker can cache resources after they are obtained, but cannot add missing GPU features, override browser security policy, or fabricate unavailable network resources.</p></section></div>`}
function render(){state.route=routeMap[currentRoute()]?currentRoute():'home';renderSidebar();let out;if(state.route==='home')out=renderHome();else if(state.route==='nexus')out=renderNexus();else if(state.route==='chains')out=window.TXMetaChain?window.TXMetaChain.render({state,domains:DOMAINS}):'<div class="empty">Meta-Chain module unavailable.</div>';else if(state.route==='status')out=renderStatus();else if(state.route==='projects')out=renderProjects();else if(state.route==='coordination')out=renderCoordination();else if(state.route==='quests')out=renderQuests();else if(state.route==='evidence')out=renderEvidence();else if(state.route==='decisions')out=renderDecisions();else if(state.route==='scenario')out=renderScenario();else if(state.route==='guides')out=renderGuides();else if(state.route==='ai')out=renderAI();else if(state.route==='about')out=renderAbout();else {const d=domainByRoute();out=d?renderDomain(d):renderHome()}$('#app').innerHTML=out;document.body.classList.remove('nav-open');syncNavButton();bindView();window.scrollTo({top:0,behavior:state.settings.reduceMotion?'auto':'smooth'})}

async function saveRecord(store,obj){obj.rev=(obj.rev||0)+1;obj.updatedAt=new Date().toISOString();await dbPut(store,obj);await reloadRecords();render();return obj}
function cleanText(v,max=500){return String(v??'').replace(/[\u0000-\u001f\u007f]/g,' ').slice(0,max)}
function sanitizeRecord(store,r){
  if(!r||typeof r!=='object'||!STORES.includes(store))return null;
  const base={id:cleanText(r.id,180),rev:Math.max(1,Math.min(1000000,Number(r.rev)||1)),updatedAt:cleanText(r.updatedAt,40)};
  if(!base.id)return null;
  const schemas={
    projects:()=>({...base,title:cleanText(r.title,120),owner:cleanText(r.owner,120),geography:cleanText(r.geography,180),outcome:cleanText(r.outcome,220),stage:cleanText(r.stage,40),privacy:cleanText(r.privacy,60),participants:cleanText(r.participants,4000),metrics:cleanText(r.metrics,4000),domains:Array.isArray(r.domains)?r.domains.filter(x=>DOMAINS.some(d=>d.id===x)).slice(0,10):[],dependencies:cleanText(r.dependencies,4000)}),
    tasks:()=>({...base,title:cleanText(r.title,180),projectId:cleanText(r.projectId,180),owner:cleanText(r.owner,120),role:cleanText(r.role,60),due:cleanText(r.due,20),domain:cleanText(r.domain,40),status:cleanText(r.status,40),detail:cleanText(r.detail,4000)}),
    comments:()=>({...base,projectId:cleanText(r.projectId,180),role:cleanText(r.role,60),author:cleanText(r.author,120),body:cleanText(r.body,4000)}),
    evidence:()=>({...base,domain:cleanText(r.domain,40),date:cleanText(r.date,20),title:cleanText(r.title,180),url:/^https?:\/\//i.test(String(r.url||''))?cleanText(r.url,1500):'',note:cleanText(r.note,4000)}),
    decisions:()=>({...base,title:cleanText(r.title,180),owner:cleanText(r.owner,120),review:cleanText(r.review,20),status:cleanText(r.status,40),rationale:cleanText(r.rationale,5000)}),
    questions:()=>({...base,title:cleanText(r.title,1500),owner:cleanText(r.owner,120),domain:cleanText(r.domain,40),status:cleanText(r.status,40)}),
    handoffs:()=>({...base,title:cleanText(r.title,180),projectId:cleanText(r.projectId,180),from:cleanText(r.from,120),to:cleanText(r.to,120),condition:cleanText(r.condition,3000),status:cleanText(r.status,40)}),
    quests:()=>({...base,title:cleanText(r.title,160),objective:cleanText(r.objective,2000),projectId:cleanText(r.projectId,180),role:cleanText(r.role,60),points:Math.max(5,Math.min(200,Number(r.points)||25)),status:cleanText(r.status,40)}),
    chains:()=>({...base,title:cleanText(r.title,160),summary:cleanText(r.summary,1200),definition:cleanText(r.definition,24000),domains:Array.isArray(r.domains)?r.domains.filter(x=>DOMAINS.some(d=>d.id===x)).slice(0,10):[],source:cleanText(r.source,240)}),
    chainRuns:()=>({...base,templateId:cleanText(r.templateId,180),title:cleanText(r.title,180),goal:cleanText(r.goal,800),geography:cleanText(r.geography,180),mode:cleanText(r.mode,40),depth:cleanText(r.depth,40),lead:cleanText(r.lead,120),domains:Array.isArray(r.domains)?r.domains.filter(x=>DOMAINS.some(d=>d.id===x)).slice(0,10):[],stageState:cleanText(r.stageState,24000),compiledProjectId:cleanText(r.compiledProjectId,180),compiledAt:cleanText(r.compiledAt,40)}),
    chainArtifacts:()=>({...base,runId:cleanText(r.runId,180),stageId:cleanText(r.stageId,180),title:cleanText(r.title,180),kind:cleanText(r.kind,60),status:cleanText(r.status,40),owner:cleanText(r.owner,120),model:cleanText(r.model,220),mode:cleanText(r.mode,60),prompt:cleanText(r.prompt,6000),content:cleanText(r.content,16000),evidenceRefs:cleanText(r.evidenceRefs,5000),assumptions:cleanText(r.assumptions,5000),hash:cleanText(r.hash,80)})
  };
  return schemas[store]?.()||null;
}
function formObj(form){return Object.fromEntries(new FormData(form).entries())}
async function updateRecord(store,id,patch){const rec=state.records[store]?.find(x=>x.id===id);if(!rec)return null;return saveRecord(store,{...rec,...patch})}
function runNexusBuilder(fd){const domains=fd.getAll('domains');const outcome=cleanText(fd.get('outcome'),220),geography=cleanText(fd.get('geography'),180),projectId=cleanText(fd.get('projectId'),180),role=cleanText(fd.get('role'),60),constraint=cleanText(fd.get('constraint'),2000);const el=$('#nexusResult');if(domains.length<2){el.textContent='Select at least two domains so the builder can create cross-domain interfaces.';return}const actions=nexusRecommendations(domains,outcome);state.lastNexusPlan={domains,outcome,geography,projectId,role,constraint,actions};const handoffs=actions.filter(a=>a.kind==='handoff'),tasks=actions.filter(a=>a.kind==='task');el.innerHTML=`<div class="toolbar"><b style="margin-right:auto">${esc(domains.length)} systems · ${tasks.length} baseline/intervention tasks · ${handoffs.length} interface handoffs</b><button class="btn primary" id="saveNexusPlan">Save as executable work</button><button class="btn" id="questNexusPlan">Create collaboration quest</button></div>${constraint?`<p class="callout warning"><b>Constraint:</b> ${esc(constraint)}</p>`:''}<div class="action-stack">${actions.map((a,i)=>`<div class="action-item ${a.kind==='handoff'?'priority-medium':'priority-low'}"><strong>${i+1}. ${esc(a.title)}</strong><span>${esc(a.detail)}</span></div>`).join('')}</div>`;$('#saveNexusPlan').onclick=saveNexusPlan;$('#questNexusPlan').onclick=async()=>{const q={id:uid('quest'),title:`Nexus quest: ${outcome}`,objective:`Close the generated cross-domain interfaces for ${outcome}. Domains: ${domains.join(', ')}.`,projectId,role,points:Math.min(150,40+domains.length*10),status:'Open'};await saveRecord('quests',q);toast('Nexus quest created')}}
async function saveNexusPlan(){const p=state.lastNexusPlan;if(!p)return;let projectId=p.projectId;if(!projectId){const project={id:uid('project'),title:`Nexus: ${p.outcome}`,owner:p.role,geography:p.geography,outcome:p.outcome,stage:'Discovery',privacy:'Public coordination',participants:p.role,metrics:'Define measurable acceptance conditions during first coordination review.',domains:p.domains,dependencies:p.constraint};await dbPut('projects',{...project,rev:1,updatedAt:new Date().toISOString()});projectId=project.id}for(const a of p.actions){if(a.kind==='task')await dbPut('tasks',{id:uid('task'),title:a.title,projectId,owner:'',role:p.role,due:'',domain:a.domain,status:'Open',detail:a.detail,rev:1,updatedAt:new Date().toISOString()});else await dbPut('handoffs',{id:uid('handoff'),title:a.title,projectId,from:a.from||p.role,to:a.to||'',condition:a.detail,status:'Pending',rev:1,updatedAt:new Date().toISOString()})}await reloadRecords();toast('Nexus plan saved as project work');nav('coordination')}

function bindView(){if(state.route==='chains'&&window.TXMetaChain)window.TXMetaChain.bind({state,domains:DOMAINS,dbPut,dbDelete,reloadRecords,render,nav,toast,uid,shareRecord,aiGenerate:window.TXAIChain?.generate});$$('[data-go]').forEach(b=>b.onclick=()=>nav(b.dataset.go));$$('[data-open-collab]').forEach(b=>b.onclick=openCollab);$$('.calc-form').forEach(f=>f.onsubmit=e=>{e.preventDefault();$('[data-result]',f).textContent=calcResult(f.dataset.kind,new FormData(f))});const pf=$('#projectForm');if(pf)pf.onsubmit=async e=>{e.preventDefault();const fd=new FormData(pf);const p={id:uid('project'),title:fd.get('title'),owner:fd.get('owner'),geography:fd.get('geography'),outcome:fd.get('outcome'),stage:fd.get('stage'),privacy:fd.get('privacy'),participants:fd.get('participants'),metrics:fd.get('metrics'),domains:fd.getAll('domains'),dependencies:fd.get('dependencies')};await saveRecord('projects',p);toast('Project saved locally')};const tf=$('#taskForm');if(tf)tf.onsubmit=async e=>{e.preventDefault();const x=formObj(tf);x.id=uid('task');await saveRecord('tasks',x);toast('Task saved')};const cf=$('#commentForm');if(cf)cf.onsubmit=async e=>{e.preventDefault();const x=formObj(cf);x.id=uid('comment');await saveRecord('comments',x);toast('Comment saved')};const qf=$('#questionForm');if(qf)qf.onsubmit=async e=>{e.preventDefault();const x=formObj(qf);x.id=uid('question');await saveRecord('questions',x);toast('Question recorded')};const hf=$('#handoffForm');if(hf)hf.onsubmit=async e=>{e.preventDefault();const x=formObj(hf);x.id=uid('handoff');await saveRecord('handoffs',x);toast('Handoff recorded')};const ef=$('#evidenceForm');if(ef)ef.onsubmit=async e=>{e.preventDefault();const x=formObj(ef);x.id=uid('evidence');await saveRecord('evidence',x);toast('Evidence added')};const df=$('#decisionForm');if(df)df.onsubmit=async e=>{e.preventDefault();const x=formObj(df);x.id=uid('decision');await saveRecord('decisions',x);toast('Decision recorded')};const qst=$('#questForm');if(qst)qst.onsubmit=async e=>{e.preventDefault();const x=formObj(qst);x.id=uid('quest');x.points=Math.max(5,Math.min(200,Number(x.points)||25));await saveRecord('quests',x);toast('Quest created')};$$('[data-quest-status]').forEach(b=>b.onclick=async()=>{await updateRecord('quests',b.dataset.questStatus,{status:b.dataset.status});toast('Quest updated')});$$('[data-record-status]').forEach(b=>b.onclick=async()=>{await updateRecord(b.dataset.recordStatus,b.dataset.id,{status:b.dataset.status});toast('Status updated')});$$('[data-delete]').forEach(b=>b.onclick=async()=>{if(confirm('Delete this local record?')){await dbDelete(b.dataset.delete,b.dataset.id);await reloadRecords();render();toast('Record deleted')}});$$('[data-export]').forEach(b=>b.onclick=exportBackup);$$('[data-share-record]').forEach(b=>b.onclick=()=>shareRecord(b.dataset.shareRecord,b.dataset.id));const sf=$('#scenarioForm');if(sf)sf.onsubmit=e=>{e.preventDefault();runScenario(new FormData(sf))};const nf=$('#nexusForm');if(nf)nf.onsubmit=e=>{e.preventDefault();runNexusBuilder(new FormData(nf))};if($('#loadAI'))$('#loadAI').onclick=()=>loadAI();if($('#downloadAI'))$('#downloadAI').onclick=()=>downloadAIModel();if($('#unloadAI'))$('#unloadAI').onclick=unloadAI;if($('#loadModelCatalog'))$('#loadModelCatalog').onclick=loadModelCatalog;if($('#autoDetectAI'))$('#autoDetectAI').onclick=()=>detectAIHardwareAndRecommend({ensureCatalog:true,announce:true,forceLightest:true});if($('#refreshAIEnv'))$('#refreshAIEnv').onclick=()=>detectAIHardwareAndRecommend({ensureCatalog:false,announce:false,forceLightest:false});if($('#persistAIStorage'))$('#persistAIStorage').onclick=requestAIStoragePersistence;if($('#testAIHosts'))$('#testAIHosts').onclick=testAIHosts;if($('#stageAIModel'))$('#stageAIModel').onclick=stageSelectedAIModel;if($('#installHostedAIPack'))$('#installHostedAIPack').onclick=installHostedAIModelPack;if($('#verifyAIStage'))$('#verifyAIStage').onclick=verifySelectedAIStage;if($('#clearAIStage'))$('#clearAIStage').onclick=clearSelectedAIStage;if($('#aiPackFolder'))$('#aiPackFolder').onchange=e=>installSelectedAIModelPack(e.target.files);if($('#testAIEndpoint'))$('#testAIEndpoint').onclick=testAIEndpoint;if($('#runResilientAI'))$('#runResilientAI').onclick=runResilientAI;if($('#retryAISafe'))$('#retryAISafe').onclick=retryAISafest;if($('#copyAIDiag'))$('#copyAIDiag').onclick=copyAIDiagnostics;if($('#aiModelSearch'))$('#aiModelSearch').oninput=renderAIModelCatalog;if($('#aiTier'))$('#aiTier').onchange=renderAIModelCatalog;if($('#aiCompat'))$('#aiCompat').onchange=renderAIModelCatalog;if($('#aiModelSort'))$('#aiModelSort').onchange=renderAIModelCatalog;if($('#aiBackend'))$('#aiBackend').onchange=async()=>{if(aiReady)toast('Unload/reload the active model to change cache backend');if(aiCatalog.length){await refreshAICacheStates();renderAIModelCatalog()}};if($('#aiStrategy'))$('#aiStrategy').onchange=()=>{if(aiReady)toast('Engine strategy applies on the next load')};if($('#runAI'))$('#runAI').onclick=()=>runAI();if($('#runFallback'))$('#runFallback').onclick=runDeterministicPlanner;if($('#aiPrompt'))$('#aiPrompt').oninput=renderAITaskAssessment;if($('#aiPlanningMode'))$('#aiPlanningMode').onchange=renderAITaskAssessment;if(state.route==='ai'&&window.TXAIDeployment)window.TXAIDeployment.bind({selectModel:async id=>{if(!aiCatalog.length)await loadModelCatalog();const m=getAIModelRecord(id);if(!m)return toast('Model is not available in the current WebLLM registry');if(!m.compatibility?.compatible){toast('That model is not compatible with the detected adapter');return}aiSelectedModel=id;renderAIModelCatalog();syncAIControls();toast('Selected '+id)},stageModel:async id=>{if(!aiCatalog.length)await loadModelCatalog();const m=getAIModelRecord(id);if(!m)return toast('Model unavailable');if(!m.compatibility?.compatible){toast('Model incompatible with detected hardware');return}aiSelectedModel=id;renderAIModelCatalog();syncAIControls();await stageSelectedAIModel()},toast});if(state.route==='ai'&&window.TXPublicInference)window.TXPublicInference.bind({toast});if(state.route==='ai'){detectAIHardwareAndRecommend({ensureCatalog:true,announce:false,forceLightest:true});renderAITaskAssessment();syncAIControls()}}

function runScenario(fd){const direct=Object.fromEntries(DOMAINS.map(d=>[d.id,Math.max(0,Math.min(5,Number(fd.get(d.id)||0)))]));const duration=Math.max(1,Math.min(1.3,Number(fd.get('duration')||1))),readiness=Math.max(0,Math.min(.4,Number(fd.get('readiness')||0))),outcome=cleanText(fd.get('outcome'),220)||'maintain essential services',geography=cleanText(fd.get('geography'),180);if(!Object.values(direct).some(v=>v>0)){$('#scenarioResult').textContent='No stressors selected.';$('#scenarioActions').textContent='Run a scenario to generate intervention tasks, evidence questions and handoffs.';return}let impact={...direct};for(let round=0;round<2;round++){const next={...impact};for(const [src,links] of Object.entries(DOMAIN_LINKS)){const sv=impact[src]||0;if(!sv)continue;for(const dst of links)next[dst]=Math.min(5,(next[dst]||0)+sv*(round?0.08:0.16))}impact=next}for(const id of Object.keys(impact))impact[id]=Math.max(0,Math.min(5,impact[id]*duration*(1-readiness)));const ranked=DOMAINS.map(d=>({d,score:impact[d.id],direct:direct[d.id]})).sort((a,b)=>b.score-a.score);const priority=ranked.filter(x=>x.score>=1).slice(0,7);const actions=priority.flatMap(({d,score,direct})=>{const depth=DOMAIN_DEPTH[d.id]||{};const p=(depth.portfolio||d.playbook)[0],f=(depth.failures||[])[0]||'loss of critical function';return [{kind:'task',domain:d.id,title:`${score>=3.5?'Urgent':'Priority'}: ${d.label} continuity action`,detail:`For ${outcome}, evaluate/implement: ${p}. Verify against local conditions and authority.`},{kind:'question',domain:d.id,title:`Evidence question: ${d.label}`,detail:`What current local evidence confirms or rejects the failure mode “${f}”? Direct entered stress: ${direct}/5; propagated planning score: ${score.toFixed(1)}/5.`}]});state.lastScenario={direct,impact,priority,actions,outcome,geography,duration,readiness};$('#scenarioResult').innerHTML=`<div class="cascade-bars">${ranked.map(({d,score,direct})=>`<div class="cascade-row"><span>${d.icon} ${esc(d.label)}</span><div class="cascade-meter"><span style="width:${(score/5*100).toFixed(1)}%"></span></div><b>${score.toFixed(1)}</b></div>`).join('')}</div><p><b>Highest coordination priorities:</b> ${priority.slice(0,4).map(x=>esc(x.d.label)).join(', ')}.</p><p class="muted">Entered stress propagates twice through documented app dependencies at 16% then 8%; duration multiplier=${duration.toFixed(2)}; readiness reduction=${Math.round(readiness*100)}%. This is a heuristic for discussion, not empirical risk calibration.</p>`;$('#scenarioActions').innerHTML=`<div class="toolbar"><b style="margin-right:auto">${actions.length} generated actions/questions</b><button class="btn primary" id="scenarioSave">Create resilience project + tasks</button><button class="btn" id="scenarioQuest">Create team quest</button></div><div class="action-stack">${actions.slice(0,14).map((a,i)=>`<div class="action-item ${i<4?'priority-high':'priority-medium'}"><strong>${esc(a.title)}</strong><span>${esc(a.detail)}</span></div>`).join('')}</div>`;$('#scenarioSave').onclick=saveScenarioPlan;$('#scenarioQuest').onclick=saveScenarioQuest}
async function saveScenarioPlan(){const s=state.lastScenario;if(!s)return;const domains=s.priority.map(x=>x.d.id);const p={id:uid('project'),title:`Cascade response: ${s.outcome}`,owner:'multidisciplinary team',geography:s.geography,outcome:s.outcome,stage:'Discovery',privacy:'Public coordination',participants:'Assign responsible organizations and affected-community representatives',metrics:'Define minimum viable service, restoration time, dependency thresholds and review triggers.',domains,dependencies:'Generated from transparent Cascade Lab heuristic; verify all assumptions locally.',rev:1,updatedAt:new Date().toISOString()};await dbPut('projects',p);for(const a of s.actions){if(a.kind==='task')await dbPut('tasks',{id:uid('task'),title:a.title,projectId:p.id,owner:'',role:'research',due:'',domain:a.domain,status:'Open',detail:a.detail,rev:1,updatedAt:new Date().toISOString()});else await dbPut('questions',{id:uid('question'),title:a.title+' — '+a.detail,owner:'evidence steward',domain:a.domain,status:'Open',rev:1,updatedAt:new Date().toISOString()})}for(let i=0;i<Math.min(4,s.priority.length-1);i++){const a=s.priority[i].d,b=s.priority[i+1].d;await dbPut('handoffs',{id:uid('handoff'),title:`Cascade interface: ${a.label} → ${b.label}`,projectId:p.id,from:a.label,to:b.label,condition:`Define the minimum service/threshold that ${b.label} requires from ${a.label} for “${s.outcome}”, plus evidence, owner and escalation trigger.`,status:'Pending',rev:1,updatedAt:new Date().toISOString()})}await reloadRecords();toast('Cascade plan converted to executable project work');nav('coordination')}
async function saveScenarioQuest(){const s=state.lastScenario;if(!s)return;await saveRecord('quests',{id:uid('quest'),title:`Cascade quest: ${s.outcome}`,objective:`Validate the top cascade assumptions, close at least one interface handoff, and attach current evidence for the highest-priority domains: ${s.priority.slice(0,5).map(x=>x.d.label).join(', ')}.`,projectId:'',role:'emergency',points:100,status:'Open'});toast('Cascade quest created')}

function exportBackup(){const payload={schema:'tx-master-os',version:5,exportedAt:new Date().toISOString(),settings:state.settings,records:state.records};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`texas-master-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
async function importBackup(file){try{if(file.size>5_000_000)throw new Error('Backup exceeds 5 MB safety limit');const x=JSON.parse(await file.text());if(x.schema!=='tx-master-os'||![1,2,3,4,5].includes(x.version))throw new Error('Unsupported backup schema');for(const store of STORES)for(const rec of (x.records?.[store]||[])){const safe=sanitizeRecord(store,rec);if(safe)await dbPut(store,safe)}await reloadRecords();render();toast('Backup imported')}catch(e){toast('Import failed: '+e.message)}}

function openSettings(){const c=$('#settingsContent');c.innerHTML=`<div class="form-grid"><div class="field"><label>Theme</label><select id="setTheme"><option value="dark">Dark</option><option value="light">Light</option></select></div><div class="field"><label>Text scale</label><select id="setScale"><option value="0.9">90%</option><option value="1">100%</option><option value="1.1">110%</option><option value="1.2">120%</option></select></div><div class="field"><label>Primary user mode</label><select id="setMode">${['household','community','educator','business','institution','government','researcher'].map(x=>`<option>${x}</option>`).join('')}</select></div><div class="field"><label><input type="checkbox" id="setMotion"> Reduce motion</label></div><div class="field"><label><input type="checkbox" id="setSkipSplash"> Skip splash on future launches</label></div><div class="field"><label><input type="checkbox" id="setAutoPublic"> Auto-connect public Commons on entry</label></div></div><hr style="border-color:var(--line)"><div class="toolbar"><button class="btn" id="backupBtn">Export JSON backup</button><label class="btn">Import backup<input id="importFile" type="file" accept="application/json" hidden></label></div><p class="muted">Preferences are stored locally. There is no automatic cross-device sync.</p>`;$('#setTheme').value=state.settings.theme;$('#setScale').value=String(state.settings.textScale);$('#setMode').value=state.settings.userMode;$('#setMotion').checked=!!state.settings.reduceMotion;$('#setSkipSplash').checked=!!state.settings.skipSplash;$('#setAutoPublic').checked=state.settings.autoPublicRoom!==false;['setTheme','setScale','setMode','setMotion','setSkipSplash','setAutoPublic'].forEach(id=>$('#'+id).onchange=()=>{state.settings.theme=$('#setTheme').value;state.settings.textScale=Number($('#setScale').value);state.settings.userMode=$('#setMode').value;state.settings.reduceMotion=$('#setMotion').checked;state.settings.skipSplash=$('#setSkipSplash').checked;state.settings.autoPublicRoom=$('#setAutoPublic').checked;saveSettings()});$('#backupBtn').onclick=exportBackup;$('#importFile').onchange=e=>e.target.files[0]&&importBackup(e.target.files[0]);openModal('settingsModal')}
let lastFocus=null;function openModal(id){lastFocus=document.activeElement;const m=$('#'+id);m.classList.add('open');m.setAttribute('aria-hidden','false');setTimeout(()=>m.querySelector('button,input,select,textarea,a[href]')?.focus(),20)}function closeModal(id){const m=$('#'+id);m.classList.remove('open');m.setAttribute('aria-hidden','true');if(lastFocus?.focus)lastFocus.focus()}

// ---------- collaboration ----------
function tip(label,text){return `<span class="tooltip" tabindex="0" data-tip="${esc(text)}" aria-label="${esc(label)}: ${esc(text)}"><b>${esc(label)}</b></span>`}
function openCollab(){const c=$('#collabContent');c.innerHTML=`<p class="callout">${tip('Room ID','A shared rendezvous name used for peer discovery. Do not put names, case numbers, addresses or secrets in it.')} and ${tip('shared password','A pre-shared secret Trystero uses to derive stronger encryption for session descriptions. It is not identity verification.')} coordinate peers. ${tip('Peer IDs','Ephemeral browser peer identifiers; they do not verify a person, employer, government or institution.')} are explicitly unverified.</p><p class="callout warning">The default public room is for presence and non-sensitive coordination only. Local records are <b>not</b> automatically broadcast as events, but peers may request the bounded shared-state snapshot once connected. Keep protected/sensitive records out of this workspace entirely if they must never be peer-shared.</p><div class="form-grid"><div class="field"><label>${tip('Room ID','Use a neutral project namespace. The public default is visible to anyone using this app and discovery strategy.')}</label><input id="roomId" value="${PUBLIC_ROOM}"></div><div class="field"><label>${tip('Shared password','Optional. Peers must know the same secret. Do not reuse account passwords.')}</label><input id="roomPassword" type="password" autocomplete="new-password"></div><div class="field"><label>${tip('Discovery strategy','How peers exchange encrypted WebRTC session descriptions. Application data travels over WebRTC after connection.')}</label><select id="roomStrategy"><option value="nostr">Nostr (default)</option><option value="mqtt">MQTT</option><option value="torrent">BitTorrent</option><option value="ipfs">IPFS</option></select></div><div class="field"><label>${tip('Disciplinary role','A self-declared coordination label only; it does not prove credentials or authority.')}</label><input id="roomRole" value="multidisciplinary contributor"></div><div class="field"><label>${tip('TURN URL','Optional fallback relay used only when direct WebRTC connectivity cannot be established.')}</label><input id="turnUrl" placeholder="turn:host:3478"></div><div class="field"><label>TURN username</label><input id="turnUser" autocomplete="off"></div><div class="field"><label>TURN credential</label><input id="turnCredential" type="password" autocomplete="new-password"></div></div><div class="toolbar" style="margin-top:12px"><button class="btn primary" id="roomConnect">Connect</button><button class="btn" id="roomDisconnect">Disconnect</button><button class="btn" id="syncNow">Request peer snapshots</button></div><div id="roomStatus" class="result">Not connected. Same-origin BroadcastChannel is available where browser origin rules allow.</div><div class="field" style="margin-top:12px"><label>Room message</label><textarea id="roomMessage" maxlength="1000" placeholder="Share non-sensitive coordination notes only."></textarea></div><button class="btn" id="roomSend">Send message</button><div id="roomLog" class="result" style="max-height:260px;overflow:auto"></div><p class="muted"><b>TURN boundary:</b> direct WebRTC cannot traverse every NAT/firewall configuration. TURN is an explicit fallback, not hidden infrastructure. Credentials entered here remain in memory for this session and are not persisted.</p>`;$('#roomConnect').onclick=connectRoom;$('#roomDisconnect').onclick=disconnectRoom;$('#roomSend').onclick=sendRoomMessage;$('#syncNow').onclick=()=>state.collab?.requestSnapshots?.();openModal('collabModal');renderRoomStatus()}
function logRoom(msg){const el=$('#roomLog');if(el){const p=document.createElement('div');p.textContent=new Date().toLocaleTimeString()+' · '+msg;el.prepend(p)}}
function renderRoomStatus(){const el=$('#roomStatus');if(!el)return;const c=state.collab;el.textContent=c?.connected?`Connected via ${c.strategy}. Peers: ${c.peers.size}. Peer IDs/roles are unverified. Snapshot sync is enabled for bounded non-sensitive coordination state.`:'Not connected to a network room. Same-origin BroadcastChannel is available where browser origin rules allow.';$('#peerDot').classList.toggle('on',!!c?.connected)}
function boundedSnapshot(){const records={};for(const store of STORES)records[store]=(state.records[store]||[]).slice(-200).map(r=>sanitizeRecord(store,r)).filter(Boolean);return {schema:'tx-master-room-snapshot',version:1,generatedAt:new Date().toISOString(),records}}
function isNewer(a,b){const ar=Number(a?.rev||0),br=Number(b?.rev||0);if(ar!==br)return ar>br;return String(a?.updatedAt||'')>String(b?.updatedAt||'')}
async function mergeSnapshot(snapshot,meta={}){if(!snapshot||snapshot.schema!=='tx-master-room-snapshot'||snapshot.version!==1)return;let merged=0;for(const store of STORES){const incoming=Array.isArray(snapshot.records?.[store])?snapshot.records[store].slice(0,200):[];for(const rec of incoming){const safe=sanitizeRecord(store,rec);if(!safe)continue;const existing=state.records[store].find(x=>x.id===safe.id);if(!existing||isNewer(safe,existing)){await dbPut(store,safe);merged++}}}if(merged){await reloadRecords();render();toast(`Merged ${merged} peer record${merged===1?'':'s'}`)}logRoom(`Snapshot from ${meta.peerId?meta.peerId.slice(0,6):'peer'}: ${merged} newer records merged`)}
async function connectRoom(opts={}){if(state.collab?.connected)disconnectRoom();const strategy=opts.strategy||$('#roomStrategy')?.value||'nostr',roomId=opts.roomId||$('#roomId')?.value.trim()||PUBLIC_ROOM,password=opts.password??$('#roomPassword')?.value??'',turnUrl=opts.turnUrl??$('#turnUrl')?.value.trim()??'',turnUser=opts.turnUser??$('#turnUser')?.value??'',turnCredential=opts.turnCredential??$('#turnCredential')?.value??'',role=opts.role||$('#roomRole')?.value||state.settings.userMode||'community';if(!roomId)return toast('Room ID required');try{const mod=await import('./collaboration.js');const conn=await mod.connectCommons({strategy,roomId,password,turnUrl,turnUser,turnCredential,role,getSnapshot:boundedSnapshot,onSnapshot:mergeSnapshot,onEvent:receivePeerEvent,onStatus:s=>{if(state.collab){state.collab.peers=new Set(s.peers||[]);renderRoomStatus();logRoom(s.message||'status')}}});state.collab={...conn,connected:true,strategy,roomId,peers:new Set(conn.getPeers?.()||[])};renderRoomStatus();logRoom(`Connected to ${roomId} via ${strategy}`);return conn}catch(e){if(!opts.silent)toast('Peer connection failed: '+e.message);logRoom('Connection error: '+e.message)}}
function disconnectRoom(){try{state.collab?.disconnect?.()}catch{}state.collab=null;renderRoomStatus();toast('Network room disconnected')}
async function sendRoomMessage(){const msg=$('#roomMessage')?.value.trim();if(!msg)return;const evt={type:'chat',id:uid('chat'),text:msg.slice(0,1000),ts:new Date().toISOString()};if(state.collab?.connected){await state.collab.send(evt);logRoom('You: '+msg)}else{broadcastLocal(evt);logRoom('Local: '+msg)}$('#roomMessage').value=''}
async function shareRecord(type,id){const store=type==='project'?'projects':type;const rec=state.records[store]?.find(x=>x.id===id);if(!rec)return toast('Record not found');if(store==='projects'&&rec.privacy==='Do not share P2P')return toast('This project is marked do not share P2P');const safe=sanitizeRecord(store,rec);if(!safe)return toast('Record failed validation');const evt={type:'record',store,record:safe,ts:new Date().toISOString()};if(state.collab?.connected){await state.collab.send(evt);toast('Shared to connected room')}else{broadcastLocal(evt);toast('Shared to same-origin local tabs')}}
async function receivePeerEvent(evt,meta={}){if(!evt||typeof evt!=='object')return;if(evt.type==='chat'){logRoom((meta.peerId?'Peer '+meta.peerId.slice(0,6):'Peer')+': '+String(evt.text||'').slice(0,1000));return}if(evt.type==='record'&&STORES.includes(evt.store)&&evt.record?.id){const safe=sanitizeRecord(evt.store,evt.record);if(!safe)return;const existing=state.records[evt.store].find(x=>x.id===safe.id);if(!existing||isNewer(safe,existing)){await dbPut(evt.store,safe);await reloadRecords();if(state.route===evt.store||(state.route==='projects'&&evt.store==='projects')||(state.route==='coordination'&&['tasks','comments','questions','handoffs'].includes(evt.store))||state.route==='quests'&&evt.store==='quests'||state.route==='chains'&&['chains','chainRuns','chainArtifacts'].includes(evt.store))render();toast('Received updated '+evt.store.replace(/s$/,''))}}}
const localBus=('BroadcastChannel'in window)?new BroadcastChannel('tx-master-local-commons-v2'):null;if(localBus)localBus.onmessage=e=>receivePeerEvent(e.data,{peerId:'local-tab'});function broadcastLocal(evt){localBus?.postMessage(evt)}
async function autoJoinPublicRoom(){if(state.settings.autoPublicRoom===false||!navigator.onLine||location.protocol==='file:'||state.collab?.connected)return;await connectRoom({roomId:PUBLIC_ROOM,strategy:'nostr',role:state.settings.userMode||'community',silent:true})}

