async function getAIAdapterCaps(force=false){if(aiAdapterCaps&&!force)return aiAdapterCaps;const caps={available:false,features:[],limits:{},info:{},error:''};try{if(!navigator.gpu){caps.error='WebGPU unavailable';aiAdapterCaps=caps;return caps}const adapter=await navigator.gpu.requestAdapter();if(!adapter){caps.error='No GPU adapter';aiAdapterCaps=caps;return caps}caps.available=true;caps.features=[...adapter.features];caps.limits={maxStorageBufferBindingSize:Number(adapter.limits?.maxStorageBufferBindingSize||0),maxBufferSize:Number(adapter.limits?.maxBufferSize||0),maxComputeWorkgroupStorageSize:Number(adapter.limits?.maxComputeWorkgroupStorageSize||0),maxComputeInvocationsPerWorkgroup:Number(adapter.limits?.maxComputeInvocationsPerWorkgroup||0)};caps.info=adapter.info||{};caps.adapter=adapter}catch(e){caps.error=String(e?.message||e)}aiAdapterCaps=caps;return caps}
