async function buildAIHardwareProfile(caps=null){if(!caps)caps=await getAIAdapterCaps();let usage=null,quota=null,persistent=null;try{if(navigator.storage?.estimate){const x=await navigator.storage.estimate();usage=Number(x.usage||0);quota=Number(x.quota||0)}if(navigator.storage?.persisted)persistent=await navigator.storage.persisted()}catch{}const deviceMemory=Number(navigator.deviceMemory)||null,cores=Number(navigator.hardwareConcurrency)||null,shaderF16=!!caps?.features?.includes('shader-f16'),maxBufferSize=Number(caps?.limits?.maxBufferSize||0),maxStorageBufferBindingSize=Number(caps?.limits?.maxStorageBufferBindingSize||0);let score=0;if(caps?.available)score+=2;if(shaderF16)score+=1;if(deviceMemory>=8)score+=2;else if(deviceMemory>=4)score+=1;if(cores>=8)score+=2;else if(cores>=4)score+=1;if(maxBufferSize>=1073741824)score+=2;else if(maxBufferSize>=536870912)score+=1;if(maxStorageBufferBindingSize>=536870912)score+=1;const deviceClass=!caps?.available?'Unavailable':score>=8?'Higher-capability':score>=5?'Moderate':'Conservative';return{at:new Date().toISOString(),deviceClass,score,webgpu:!!caps?.available,shaderF16,deviceMemory,cores,maxBufferSize,maxStorageBufferBindingSize,usage,quota,persistent,secureContext:isSecureContext,online:navigator.onLine,adapter:[caps?.info?.vendor,caps?.info?.architecture,caps?.info?.device].filter(Boolean).join(' · ')||null}}
function computeAIRecommendations(profile=aiHardwareProfile){const models=compatibleAIModels();if(!models.length)return{lightest:null,balanced:null,capacity:null,profile};const lightest=models[0];const maxTier=profile?.deviceClass==='Higher-capability'?'medium':profile?.deviceClass==='Moderate'?'light':'tiny';const rank={tiny:0,light:1,medium:2,heavy:3,extreme:4,unknown:5},pool=models.filter(m=>(rank[m.tier]??9)<=rank[maxTier]);const usable=pool.length?pool:models.slice(0,1);const balanced=usable[Math.min(usable.length-1,Math.max(0,Math.floor((usable.length-1)*.5)))];const capacity=usable[usable.length-1];return{lightest,balanced,capacity,profile}}
function recommendationReason(kind,model,profile){if(!model)return'No compatible model detected.';if(kind==='lightest')return`Lowest declared VRAM among models compatible with the reported WebGPU adapter. Safest default for first load.`;if(kind==='balanced')return`Mid-range compatible choice inside the ${profile?.deviceClass||'detected'} hardware envelope. Optional if the lightest model runs comfortably.`;return`Largest compatible model kept inside the detector’s ${profile?.deviceClass||'detected'} compute tier. Treat this as an experiment, not a guarantee.`}

function parseModelParameterBillions(model){const id=String(model?.model_id||'');let m=id.match(/(?:^|[-_])(\d+(?:\.\d+)?)B(?:[-_]|$)/i);if(m)return Number(m[1]);m=id.match(/(?:^|[-_])(\d+(?:\.\d+)?)M(?:[-_]|$)/i);if(m)return Number(m[1])/1000;return null}
function aiTaskModeFromPrompt(prompt,override='auto'){if(override&&override!=='auto')return override;const q=String(prompt||'').toLowerCase();let score=0;const strong=['comprehensive','exhaustive','infrastructure','implementation','master plan','strategy','cross-domain','multidisciplinary','roadmap','governance','budget','stakeholder','phased','systems','regional','countywide','statewide'];for(const k of strong)if(q.includes(k))score++;if(q.length>220)score+=2;else if(q.length>100)score++;const domainHits=DOMAINS.filter(d=>q.includes(d.id)||q.includes(d.label.toLowerCase().split(' ')[0])||d.modules.some(m=>q.includes(m.toLowerCase()))).length;if(domainHits>=3)score+=2;else if(domainHits>=2)score++;return score>=7?'expert':score>=3?'comprehensive':'fast'}
function analyzeAITask(prompt){const mode=aiTaskModeFromPrompt(prompt,$('#aiPlanningMode')?.value||'auto'),q=String(prompt||'').toLowerCase();let minParams=mode==='expert'?2:mode==='comprehensive'?1:0;let minVram=mode==='expert'?1800:mode==='comprehensive'?900:0;const domains=DOMAINS.filter(d=>q.includes(d.id)||q.includes(d.label.toLowerCase().split(' ')[0])||d.modules.some(m=>q.includes(m.toLowerCase())));const edible=/edible|food forest|fruit tree|orchard|agroforest|community garden|urban agriculture|food infrastructure/.test(q);if(edible&&!domains.some(d=>d.id==='food'))domains.unshift(DOMAINS.find(d=>d.id==='food'));return{mode,minParams,minVram,domains:[...new Map(domains.filter(Boolean).map(d=>[d.id,d])).values()].slice(0,7),edible,prompt:String(prompt||'').trim()}}
function modelTaskFitness(model,task){if(!model?.compatibility?.compatible)return-1e9;const p=parseModelParameterBillions(model),v=Number(model.vram)||0,id=String(model.model_id||'').toLowerCase();let score=0;if(p!=null)score+=Math.min(p,8)*10;else score+=Math.min(v/500,12);if(id.includes('instruct'))score+=4;if(id.includes('llama-3.2'))score+=3;if(id.includes('phi-3.5'))score+=3;if(id.includes('gemma-2'))score+=2;if(id.includes('hermes'))score+=2;if(task.mode==='fast')score-=v/1200;else if(task.mode==='comprehensive'){if((p||0)>=1)score+=12;if(v>=900)score+=4}else if(task.mode==='expert'){if((p||0)>=2)score+=18;if(v>=1800)score+=6}if(model.cached)score+=8;return score}
function recommendModelForTask(task,{cachedOnly=false}={}){const models=compatibleAIModels().filter(m=>!cachedOnly||m.cached);if(!models.length)return null;const threshold=models.filter(m=>(parseModelParameterBillions(m)||0)>=task.minParams||Number(m.vram||0)>=task.minVram);const pool=threshold.length?threshold:models;return [...pool].sort((a,b)=>modelTaskFitness(b,task)-modelTaskFitness(a,task))[0]||null}
