function renderAITaskAssessment(){const el=$('#aiTaskAssessment'),prompt=$('#aiPrompt')?.value||'';if(!el)return;if(!prompt.trim()){el.textContent='Type a request to see task complexity, recommended model class and generation strategy.';return}const task=analyzeAITask(prompt),rec=recommendModelForTask(task),cached=recommendModelForTask(task,{cachedOnly:true}),current=getAIModelRecord(aiSelectedModel);const label=task.mode==='expert'?'Expert implementation':task.mode==='comprehensive'?'Comprehensive planning':'Fast / concise';el.innerHTML=`<div class="toolbar"><b style="margin-right:auto">${esc(label)}</b><span class="pill">${task.domains.length||1} domain${task.domains.length===1?'':'s'}</span></div><p><b>Current:</b> ${esc(current?.model_id||aiSelectedModel)}${current?` · ${fmtMB(current.vram)} · ${esc(taskFitLabel(current,task))}`:''}</p><p><b>Task recommendation:</b> ${rec?`${esc(rec.model_id)} · ${fmtMB(rec.vram)}`:'No compatible model currently detected.'}</p>${cached&&cached.model_id!==aiSelectedModel?`<p><b>Cached upgrade available:</b> ${esc(cached.model_id)}. Adaptive mode can switch automatically.</p>`:''}<p class="muted">The recommendation is heuristic. For comprehensive work, ≥1B parameters is preferred when hardware permits; ≥2B is preferred for expert/implementation synthesis. Small models still receive a detailed scaffold and weak-response retry.</p>`}
function buildPlanningScaffold(task){const ds=task.domains.length?task.domains:DOMAINS.filter(d=>['food','water','resilience','learning','connectivity'].includes(d.id));const sections=['Executive objective and explicit assumptions','Regional/site context and constraints','System architecture and intervention portfolio','Site typologies and prioritization criteria','Water, soil, energy, access and maintenance dependencies','Implementation phases: first 30 days, 90 days, 1 year, 3–5 years','Roles: families, community groups, schools, businesses, institutions and government','Budget/resource categories and funding questions (no invented prices)','Operations, maintenance, stewardship and succession','Metrics, monitoring, evidence and review gates','Risks, failure modes, safety/accessibility constraints and mitigations','Cross-domain handoffs and decision owners','Evidence that must be locally verified before implementation'];if(task.edible)sections.splice(3,0,'Edible-infrastructure palette by function: canopy trees, understory, shrubs/vines, herbs/groundcovers, annual beds, pollinator habitat and seed/nursery capacity; only name locally suitable species when confident, otherwise state selection criteria and flag local verification');const domainLines=ds.map(d=>`- ${d.label}: principle=${d.principle} | useful modules=${d.modules.slice(0,8).join(', ')} | first playbook step=${d.playbook[0]}`);return `PLANNING SCAFFOLD\nRequired sections:\n${sections.map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\nRelevant systems:\n${domainLines.join('\n')}\n\nOutput rules:\n- Directly complete the planning task; do not redirect the user merely because agencies or stakeholders should participate.\n- When exact local facts are unavailable, state an assumption or a verification task instead of inventing a fact.\n- Distinguish bundled facts, inference, scenario and recommendation.\n- Make the plan actionable with owners, sequencing, acceptance conditions, metrics and failure checks.\n- Treat agencies/stakeholders as collaborators inside the plan, not substitutes for producing the plan.\n- For public-space or infrastructure work, include permitting, utilities, accessibility, maintenance, liability/safety and long-term stewardship checks where relevant.`}
function buildAISystemPrompt(task){return `You are the on-device planning engine inside Texas Master Systems OS. You ARE capable of drafting practical plans, project charters, implementation roadmaps and multidisciplinary infrastructure concepts. Do not apologize, claim you lack the capability to plan, or tell the user to contact stakeholders instead of answering. Stakeholders and agencies may be included as responsible parties or verification sources.\n\nYour job is to produce the most useful draft possible from the information available. If local facts are missing, label assumptions and verification needs; never fabricate current program status, laws, prices or site-specific facts. Separate fact, inference, scenario and recommendation.\n\nFor ${task.mode} requests, favor concrete actions, phases, owners, handoffs, metrics, maintenance, failure modes and evidence requirements. Use clear headings and substantive detail. ${task.edible?'For edible infrastructure, think in systems: site suitability, water, soil, edible plant functions, propagation/nursery capacity, access, harvesting, food safety, maintenance, pollinators, education, distribution and stewardship.':''}`}
