function deterministicPlannerText(prompt,task=analyzeAITask(prompt)){const ds=task.domains.length?task.domains:DOMAINS.filter(d=>['food','water','resilience','learning'].includes(d.id));const edible=task.edible?['Build a site inventory covering schools, parks, libraries, community facilities, compatible rights-of-way and private/community partner land.','Classify candidate sites by water access, soil condition/contamination screening, sun, utilities, accessibility, maintenance ownership and harvest access.','Use a layered edible-landscape portfolio: canopy fruit/nut trees where suitable; smaller fruiting trees/shrubs; vines/perennials; herbs/groundcovers; annual demonstration beds; pollinator support; nursery/propagation nodes. Select species/cultivars using locally verified heat, freeze, soil, water and pest suitability.','Create nursery and replacement-stock capacity so survival and expansion do not depend on repeated retail purchases.','Define harvest, food-safety, accessibility and surplus-distribution protocols before scale-up.']:[];return [`Adaptive deterministic plan for: ${prompt}`,'','1. Objective & assumptions',`- Produce a phased, maintainable ${task.mode} plan. Treat location-specific facts as items to verify before implementation.`,`- Primary systems: ${ds.map(d=>d.label).join(', ')}.`,'','2. Baseline & mapping','- Map assets, gaps, vulnerable populations, current programs, land/control, utilities, water, maintenance capacity and existing community partners.','- Give every candidate intervention an owner, service area, dependency list, evidence date and success metric.','',...(edible.length?['3. Edible infrastructure architecture',...edible.map(x=>'- '+x),'']:[]),`${edible.length?'4':'3'}. Cross-domain design`,...ds.map(d=>`- ${d.label}: ${d.playbook[0]} Then test: ${(DOMAIN_DEPTH[d.id]?.failures||[])[0]||'loss of critical service continuity'}.`),'',`${edible.length?'5':'4'}. Phasing`,'- First 30 days: inventory, governance, pilot criteria, evidence collection and partner commitments.','- 31–90 days: launch representative pilots, establish maintenance/monitoring protocols, record costs and failure modes.','- 3–12 months: expand successful typologies, train stewards, integrate procurement and continuity plans.','- Years 2–5: scale by measured survival/use/access outcomes rather than planting/output counts alone.','',`${edible.length?'6':'5'}. Governance & collaboration`,'- Decision owner: lawful site/asset authority.','- Technical owners: domain specialists responsible for design and acceptance criteria.','- Community/family users: accessibility, usability and stewardship feedback.','- Evidence steward: source/date/uncertainty register.','- Operations owner: maintenance funding, inspections, replacements and incident response.','',`${edible.length?'7':'6'}. Metrics`,'- Coverage/access: people and priority sites within practical access.','- Reliability: survival/uptime/continuity and replacement rate.','- Equity: burden and benefit by geography/population without storing unnecessary sensitive data.','- Operations: maintenance hours/cost, unresolved defects, handoff completion.','- Outcomes: service delivered, usage/harvest where relevant, and resilience during disruptions.','',`${edible.length?'8':'7'}. Before implementation`,'- Verify applicable site authority, utilities, codes/permits, accessibility, environmental/soil constraints, water availability, procurement rules and maintenance responsibility.','- Convert assumptions into evidence questions and decision gates rather than treating them as facts.'].join('\n')}

function renderAIRecommendations(){const el=$('#aiRecommendations');if(!el)return;const p=aiHardwareProfile;if(!p){el.innerHTML='<div class="result">Hardware profile has not been detected yet.</div>';return}if(!aiCatalog.length){el.innerHTML=`<div class="result"><b>${esc(p.deviceClass)}</b> hardware profile detected. Loading the model registry is required before model recommendations can be ranked.</div>`;return}aiRecommendations=computeAIRecommendations(p);const picks=[['lightest','Default · lightest compatible',aiRecommendations.lightest],['balanced','Balanced compute',aiRecommendations.balanced],['capacity','Higher-capacity candidate',aiRecommendations.capacity]].filter((x,i,a)=>x[2]&&a.findIndex(y=>y[2]?.model_id===x[2]?.model_id)===i);el.innerHTML=`<div class="recommendation-head"><div><div class="eyebrow">Autodetected hardware profile</div><h3>${esc(p.deviceClass)}</h3><p class="muted">Heuristic score ${p.score}/10 · ${p.shaderF16?'shader-f16 available':'shader-f16 not exposed'} · ${p.deviceMemory?`${p.deviceMemory} GB browser-reported system memory`:'system-memory hint unavailable'} · ${p.cores?`${p.cores} logical CPU threads`:'CPU concurrency unavailable'}. This does not measure GPU VRAM.</p></div><span class="pill">${compatibleAIModels().length} compatible</span></div><div class="recommendation-grid">${picks.map(([kind,label,m])=>`<article class="recommendation-card ${kind==='lightest'?'recommended':''}"><div class="toolbar"><b>${esc(label)}</b>${kind==='lightest'?'<span class="pill compat-ok">Default</span>':''}</div><h4>${esc(m.model_id)}</h4><p><b>${fmtMB(m.vram)}</b> declared VRAM · ${esc(aiTierLabel(m.tier))}</p><p class="muted">${esc(recommendationReason(kind,m,p))}</p><button class="btn ${m.model_id===aiSelectedModel?'primary':''}" data-ai-recommend="${esc(m.model_id)}">${m.model_id===aiSelectedModel?'Selected':'Use this model'}</button></article>`).join('')}</div>`;bindAIRecommendationButtons()}
function bindAIRecommendationButtons(){$$('[data-ai-recommend]').forEach(b=>b.onclick=()=>{aiManualSelection=true;selectAIModel(b.dataset.aiRecommend);renderAIRecommendations()})}
async function detectAIHardwareAndRecommend({ensureCatalog=true,announce=true,forceLightest=true}={}){if(aiAutodetectRunning)return;aiAutodetectRunning=true;const btn=$('#autoDetectAI');if(btn){btn.disabled=true;btn.textContent='Detecting…'}try{const caps=await getAIAdapterCaps(true);aiHardwareProfile=await buildAIHardwareProfile(caps);await renderAIEnvironment();if(ensureCatalog&&!aiCatalog.length)await loadModelCatalog({auto:true});if(aiCatalog.length){aiCatalog.forEach(m=>m.compatibility=evaluateAIModelCompatibility(m,caps));aiRecommendations=computeAIRecommendations(aiHardwareProfile);if(forceLightest&&aiRecommendations.lightest){aiSelectedModel=aiRecommendations.lightest.model_id;aiManualSelection=false}renderAIModelCatalog();renderAIRecommendations();syncAIControls()}else renderAIRecommendations();if(announce){const light=aiRecommendations?.lightest;toast(light?`Hardware detected: ${aiHardwareProfile.deviceClass}. Defaulted to ${light.model_id}.`:`Hardware detected: ${aiHardwareProfile.deviceClass}. No compatible model found.`)}}catch(e){showAIDiagnostics(classifyAIError(e,'hardware-autodetect'));const el=$('#aiRecommendations');if(el)el.innerHTML=`<div class="result">Hardware autodetect failed: ${esc(String(e?.message||e))}</div>`}finally{aiAutodetectRunning=false;if(btn){btn.disabled=false;btn.textContent='Autodetect hardware & recommend'}}}
async function getWebLLM(force=false){if(webllmRuntime&&!force)return webllmRuntime;if(force){webllmRuntime=null;webllmRuntimeSource=''}const status=$('#aiCatalogStatus'),errors=[];for(const cdn of WEBLLM_CDNS){try{if(status)status.textContent=`Loading WebLLM 0.2.85 runtime from ${cdn.label}…`;const mod=await import(cdn.url);webllmRuntime=mod;webllmRuntimeSource=cdn.url;return mod}catch(e){errors.push(`${cdn.label}: ${String(e?.message||e)}`)}}throw new Error('WebLLM runtime CDN import failed. '+errors.join(' | '))}
function getAIBackend(){return $('#aiBackend')?.value||'cache'}
function getAIStrategy(){return $('#aiStrategy')?.value||'direct-worker'}
function getAIAppConfig(webllm,backend=getAIBackend()){const cfg={...webllm.prebuiltAppConfig,cacheBackend:backend};if(backend==='opfs')cfg.opfsAccessMode='auto';return cfg}
async function renderAIEnvironment(){const el=$('#aiEnvironment');if(!el)return;let storage='Unknown',persistent='Unknown';const caps=await getAIAdapterCaps(true),info=caps.info||{},adapter=[info.vendor,info.architecture,info.device].filter(Boolean).join(' · ')||(caps.available?'Adapter available':caps.error||'Unavailable'),f16=caps.available?(caps.features.includes('shader-f16')?'Supported':'Not exposed'):'Unavailable';aiHardwareProfile=await buildAIHardwareProfile(caps);try{if(aiHardwareProfile.quota!==null)storage=`${fmtMB((aiHardwareProfile.usage||0)/1048576)} / ${fmtMB((aiHardwareProfile.quota||0)/1048576)}`;persistent=aiHardwareProfile.persistent===null?'Unknown':aiHardwareProfile.persistent?'Yes':'No'}catch{}el.innerHTML=`<div class="pulse-cell"><span>Hardware profile</span><strong style="font-size:1rem">${esc(aiHardwareProfile.deviceClass)}</strong></div><div class="pulse-cell"><span>WebGPU</span><strong>${caps.available?'Available':'Unavailable'}</strong></div><div class="pulse-cell"><span>shader-f16</span><strong>${esc(f16)}</strong></div><div class="pulse-cell"><span>CPU threads</span><strong>${esc(aiHardwareProfile.cores||'Unknown')}</strong></div><div class="pulse-cell"><span>System memory hint</span><strong style="font-size:1rem">${aiHardwareProfile.deviceMemory?esc(aiHardwareProfile.deviceMemory+' GB'):'Unknown'}</strong></div><div class="pulse-cell"><span>Max GPU buffer</span><strong style="font-size:1rem">${caps.limits?.maxBufferSize?fmtMB(caps.limits.maxBufferSize/1048576):'Unknown'}</strong></div><div class="pulse-cell"><span>Adapter</span><strong style="font-size:.9rem">${esc(adapter)}</strong></div><div class="pulse-cell"><span>Origin storage</span><strong style="font-size:1rem">${esc(storage)}</strong></div><div class="pulse-cell"><span>Persistent</span><strong>${esc(persistent)}</strong></div><div class="pulse-cell"><span>Runtime source</span><strong style="font-size:.78rem">${esc(webllmRuntimeSource||'Not loaded')}</strong></div><div class="pulse-cell"><span>Engine mode</span><strong style="font-size:.9rem">${esc(aiEngineMode||'None')}</strong></div>`;if(aiCatalog.length){aiCatalog.forEach(m=>m.compatibility=evaluateAIModelCompatibility(m,caps));aiRecommendations=computeAIRecommendations(aiHardwareProfile);renderAIModelCatalog();renderAIRecommendations()}}
async function requestAIStoragePersistence(){if(!navigator.storage?.persist)return toast('Persistent storage request is not supported by this browser');try{const ok=await navigator.storage.persist();toast(ok?'Persistent storage granted':'Persistent storage not granted');renderAIEnvironment()}catch(e){toast('Storage request failed: '+e.message)}}
async function loadModelCatalog(opts={}){const status=$('#aiCatalogStatus'),btn=$('#loadModelCatalog');if(btn)btn.disabled=true;try{const webllm=await getWebLLM(),caps=await getAIAdapterCaps(true);const list=(webllm.prebuiltAppConfig?.model_list||[]).filter(m=>!m.model_type||String(m.model_type).toLowerCase()==='llm').map(m=>{const x={...m,vram:Number(m.vram_required_MB),tier:aiTierFor(Number(m.vram_required_MB))};x.compatibility=evaluateAIModelCompatibility(x,caps);return x});aiCatalog=list;const best=bestCompatibleAIModel(),current=getAIModelRecord(aiSelectedModel);if(best&&(!aiManualSelection||!current?.compatibility?.compatible))aiSelectedModel=best.model_id;status.textContent=`${list.length} chat models found via ${webllmRuntimeSource}. ${list.filter(m=>m.compatibility?.compatible).length} match this adapter's reported WebGPU features. Checking local cache status…`;await refreshAICacheStates();if(!aiHardwareProfile)aiHardwareProfile=await buildAIHardwareProfile(caps);aiRecommendations=computeAIRecommendations(aiHardwareProfile);renderAIModelCatalog();renderAIRecommendations();status.innerHTML=`<b>${list.filter(m=>m.compatibility?.compatible).length}/${list.length}</b> models compatible with reported adapter features.${caps.available&&!caps.features.includes('shader-f16')?' <b>shader-f16 is not exposed</b>, so f16-required models are disabled.':''}${best?` Default lightest-compatible model: <b>${esc(best.model_id)}</b> (${fmtMB(best.vram)}).`:''}`;await renderAIEnvironment()}catch(e){if(status)status.textContent='Could not load model catalog: '+String(e.message||e);showAIDiagnostics(classifyAIError(e,'runtime-import'))}finally{if(btn)btn.disabled=false}}
async function refreshAICacheStates(){if(!aiCatalog.length||!webllmRuntime)return;const config=getAIAppConfig(webllmRuntime);await Promise.all(aiCatalog.map(async m=>{try{m.cached=await webllmRuntime.hasModelInCache(m.model_id,config)}catch{m.cached=false}}))}
function filteredAIModels(){const q=($('#aiModelSearch')?.value||'').trim().toLowerCase(),tier=$('#aiTier')?.value||'all',compat=$('#aiCompat')?.value||'compatible',sort=$('#aiModelSort')?.value||'vram-asc';let arr=aiCatalog.filter(m=>(tier==='all'||m.tier===tier)&&(compat==='all'||(compat==='compatible'?m.compatibility?.compatible:!m.compatibility?.compatible))&&(!q||(m.model_id+' '+(m.model||'')).toLowerCase().includes(q)));arr=[...arr];if(sort==='name')arr.sort((a,b)=>a.model_id.localeCompare(b.model_id));else if(sort==='vram-desc')arr.sort((a,b)=>(Number.isFinite(b.vram)?b.vram:-1)-(Number.isFinite(a.vram)?a.vram:-1));else arr.sort((a,b)=>(Number.isFinite(a.vram)?a.vram:1e12)-(Number.isFinite(b.vram)?b.vram:1e12));return arr}
function renderAIModelCatalog(){const el=$('#aiModelCatalog');if(!el)return;const arr=filteredAIModels();if(!arr.length){el.innerHTML='<div class="empty">No models match these filters.</div>';return}const q=($('#aiModelSearch')?.value||'').trim(),filterTier=$('#aiTier')?.value||'all',order=['tiny','light','medium','heavy','extreme','unknown'];const groups=order.map(t=>[t,arr.filter(m=>m.tier===t)]).filter(([,ms])=>ms.length);el.innerHTML=groups.map(([tier,models])=>{const cached=models.filter(m=>m.cached).length,ok=models.filter(m=>m.compatibility?.compatible).length,selected=models.some(m=>m.model_id===aiSelectedModel),open=(q||filterTier!=='all'||selected)?' open':'';return `<details class="model-tier-group"${open}><summary><span><span class="model-tier tier-${tier}">${aiTierLabel(tier)}</span> <b>${models.length} model${models.length===1?'':'s'}</b></span><span class="muted">${ok} compatible · ${cached} cached</span></summary><div class="model-tier-list">${models.map(m=>{const c=m.compatibility||{compatible:false,reason:'Compatibility not checked'},disabled=c.compatible?'':' disabled';return `<details class="model-entry ${m.model_id===aiSelectedModel?'selected':''} ${c.compatible?'compatible':'incompatible'}" ${m.model_id===aiSelectedModel?'open':''}><summary><span class="model-entry-name">${esc(m.model_id)}</span><span class="model-entry-meta"><b>${fmtMB(m.vram)}</b><span class="pill ${c.compatible?'compat-ok':'compat-bad'}">${c.compatible?'Compatible':'Incompatible'}</span><span class="pill ${m.cached?'cached':''}">${m.cached?'Cached':'Not cached'}</span></span></summary><div class="model-entry-body"><div class="model-specs"><span>${m.low_resource_required?'Low-resource mode':'Standard resource mode'}</span><span>${m.overrides?.context_window_size?esc(String(m.overrides.context_window_size))+' ctx':'Context varies'}</span><span>Required features: ${esc((m.required_features||[]).join(', ')||'none declared')}</span><span class="${c.compatible?'muted':'compat-reason'}">${esc(c.reason)}</span><span class="muted">Model host: ${esc((()=>{try{return new URL(m.model).hostname}catch{return 'unknown'}})())}</span></div><div class="toolbar"><button class="btn ${m.model_id===aiSelectedModel?'primary':''}" data-ai-select="${esc(m.model_id)}"${disabled}>${m.model_id===aiSelectedModel?'Selected':'Select'}</button><button class="btn" data-ai-cache="${esc(m.model_id)}"${disabled}>${m.cached?'Verify/re-cache':'Download & cache'}</button>${m.cached?`<button class="btn" data-ai-delete="${esc(m.model_id)}">Delete cache</button>`:''}</div></div></details>`}).join('')}</div></details>`}).join('');bindAIModelButtons();syncAIControls()}
function selectAIModel(id){const rec=getAIModelRecord(id);if(rec?.compatibility&&!rec.compatibility.compatible){toast('That model is incompatible with the reported WebGPU adapter: '+rec.compatibility.reason);return}aiSelectedModel=id;renderAIModelCatalog();const status=$('#aiStatus');if(status)status.textContent=`Selected ${id}. ${aiReady?'A model is currently loaded; choose Load selected model to switch.':'Ready to load or cache.'}`}
function syncAIControls(){const hasCatalog=!!aiCatalog.length,rec=getAIModelRecord(aiSelectedModel),compatible=!rec?.compatibility||rec.compatibility.compatible;const l=$('#loadAI'),d=$('#downloadAI'),u=$('#unloadAI'),r=$('#runAI'),retry=$('#retryAISafe'),copy=$('#copyAIDiag'),probe=$('#testAIHosts');if(l)l.disabled=aiBusy||!hasCatalog||!navigator.gpu||!compatible;if(d)d.disabled=aiBusy||!hasCatalog||!navigator.gpu||!compatible;if(u)u.disabled=aiBusy||!aiEngine;if(r)r.disabled=aiBusy||!aiReady;if(retry)retry.disabled=aiBusy||!aiLastFailure||!hasCatalog||!navigator.gpu||!compatible;if(copy)copy.disabled=!aiLastFailure;if(probe)probe.disabled=aiBusy||!hasCatalog}
function bindAIModelButtons(){$$('[data-ai-select]').forEach(b=>b.onclick=()=>{aiManualSelection=true;selectAIModel(b.dataset.aiSelect);renderAIRecommendations()});$$('[data-ai-cache]').forEach(b=>b.onclick=()=>downloadAIModel(b.dataset.aiCache));$$('[data-ai-delete]').forEach(b=>b.onclick=()=>deleteAIModelCache(b.dataset.aiDelete))}
function getAIModelRecord(modelId){return aiCatalog.find(m=>m.model_id===modelId)||(webllmRuntime?.prebuiltAppConfig?.model_list||[]).find(m=>m.model_id===modelId)||null}
function setAIStatus(msg){const el=$('#aiStatus');if(el)el.textContent=msg}
function classifyAIError(err,stage='unknown',mode=aiEngineMode||'unresolved'){const message=String(err?.message||err||'Unknown error'),raw=String(err?.stack||message),t=message.toLowerCase();let kind='unknown',hint='Try the lowest-VRAM model marked Compatible, Cache API, and run Test model hosts. Copy diagnostics if it still fails.';if(t.includes('shader-f16')||t.includes('required webgpu feature')||t.includes('required feature')||t.includes('maxstoragebuffer')||t.includes('gpuadapter')||t.includes('gpudevice')||t.includes('webgpu is unavailable')){kind='gpu-compatibility';hint=t.includes('shader-f16')?'This GPU adapter does not expose shader-f16. Choose a model marked Compatible—typically an f32/q4f32 variant rather than this f16-required model. This is not a network failure.':'The GPU/browser does not meet this model’s WebGPU requirements. Choose a model marked Compatible in the catalog.'}else if(t.includes('out of memory')||t.includes('oom')||t.includes('memory allocation')){kind='gpu-memory';hint='The model did not fit available GPU memory. Retry a lower-VRAM compatible model or reduce context requirements.'}else if(t.includes('quota')||t.includes('storage')&&t.includes('exceed')){kind='storage';hint='Browser storage is full or quota is too small. Free site storage, request persistent storage, or choose a smaller model.'}else if(t.includes('opfs')){kind='cache-backend';hint='OPFS failed. Switch the cache backend to Cache API and retry.'}else if(t.includes('failed to fetch')||t.includes('network')||t.includes('cors')||t.includes('cdn')||/^http(?:s)? error/.test(t)){kind='network';hint='A runtime/model artifact request failed. Run Test model hosts to determine whether the runtime CDN, Hugging Face model config, or compiled WebGPU library route is unreachable.'}else if(t.includes('modelnotfound')||t.includes('cannot find model')||t.includes('model not found')){kind='registry';hint='The selected model was not found in the pinned WebLLM registry. Reload the catalog.'}else if(t.includes('worker')||t.includes('dirname')||t.includes('import')){kind='runtime-path';hint='The engine/runtime module path failed. Switch between Direct only and Worker only to isolate that class of failure.'}return{at:new Date().toISOString(),model:aiSelectedModel,backend:getAIBackend(),strategy:getAIStrategy(),engineMode:mode,runtimeSource:webllmRuntimeSource,stage,kind,hint,message,raw}}
async function aiPreflight(modelId,backend=getAIBackend()){const webllm=await getWebLLM();const rec=(webllm.prebuiltAppConfig?.model_list||[]).find(m=>m.model_id===modelId);if(!rec)throw new Error('ModelNotFound: '+modelId+' is not present in WebLLM prebuiltAppConfig.model_list');if(!navigator.onLine){const cached=await webllm.hasModelInCache(modelId,getAIAppConfig(webllm,backend));if(!cached)throw new Error('Network unavailable and selected model is not already cached')}if(backend==='cache'&&!('caches'in window))throw new Error('Cache API unavailable');if(backend==='indexeddb'&&!('indexedDB'in window))throw new Error('IndexedDB unavailable');if(backend==='opfs'&&!navigator.storage?.getDirectory)throw new Error('OPFS unavailable: navigator.storage.getDirectory is not supported');const caps=await getAIAdapterCaps(true);if(!caps.available)throw new Error(caps.error||'WebGPU is unavailable in this browser/context');const compatibility=evaluateAIModelCompatibility(rec,caps);if(!compatibility.compatible){const e=new Error('GPU compatibility: '+compatibility.reason);e.name='GPUCompatibilityError';e.missingFeatures=compatibility.missingFeatures;throw e}return{webllm,rec,adapter:caps.adapter,config:getAIAppConfig(webllm,backend),caps}}
async function makeDirectAIEngine(modelId,{backend=getAIBackend(),cacheOnly=false}={}){const {webllm,config}=await aiPreflight(modelId,backend);const status=$('#aiStatus');const progress=p=>{if(status)status.textContent=(cacheOnly?'Direct-engine cache: ':'Direct-engine load: ')+(p?.text||`${Math.round((p?.progress||0)*100)}%`)};const opts=cacheOnly?{context_window_size:1024,prefill_chunk_size:512}:undefined;return await webllm.CreateMLCEngine(modelId,{appConfig:config,initProgressCallback:progress,logLevel:'INFO'},opts)}
async function makeWorkerAIEngine(modelId,{backend=getAIBackend(),cacheOnly=false,assignGlobal=false}={}){const {webllm,config}=await aiPreflight(modelId,backend);const status=$('#aiStatus');const worker=new Worker('./webllm-worker.js',{type:'module'});try{const engine=await webllm.CreateWebWorkerMLCEngine(worker,modelId,{appConfig:config,initProgressCallback:p=>{if(status)status.textContent=(cacheOnly?'Worker cache: ':'Worker load: ')+(p?.text||`${Math.round((p?.progress||0)*100)}%`)},logLevel:'WARN'});if(assignGlobal)aiWorker=worker;else engine.__txWorker=worker;return engine}catch(e){worker.terminate();throw e}}
async function verifyAICache(modelId,backend=getAIBackend()){const webllm=await getWebLLM();return await webllm.hasModelInCache(modelId,getAIAppConfig(webllm,backend))}
async function copyAIDiagnostics(){if(!aiLastFailure)return;const txt=JSON.stringify({...aiLastFailure,userAgent:navigator.userAgent,secureContext:isSecureContext,online:navigator.onLine},null,2);try{await navigator.clipboard.writeText(txt);toast('Diagnostics copied')}catch{toast('Could not copy diagnostics')}}
async function createByStrategy(modelId,{backend=getAIBackend(),cacheOnly=false,assignGlobal=false,strategy=getAIStrategy()}={}){const attempts=strategy==='direct-only'?['direct']:strategy==='worker-only'?['worker']:['direct','worker'];const failures=[];for(const mode of attempts){try{aiEngineMode=mode;setAIStatus(`${cacheOnly?'Caching':'Loading'} ${modelId} via ${mode} engine…`);if(mode==='direct')return{engine:await makeDirectAIEngine(modelId,{backend,cacheOnly}),mode};return{engine:await makeWorkerAIEngine(modelId,{backend,cacheOnly,assignGlobal}),mode}}catch(e){failures.push(`${mode}: ${String(e?.message||e)}`);if(mode==='worker'&&aiWorker){aiWorker.terminate();aiWorker=null}}}const e=new Error(failures.join(' | '));e.engineAttempts=failures;throw e}
async function loadAI(modelId=aiSelectedModel){const btn=$('#loadAI');if(btn)btn.disabled=true;aiReady=false;aiBusy=true;aiLastFailure=null;syncAIControls();try{if(aiEngine){try{await aiEngine.unload()}catch{}aiEngine=null}if(aiWorker){aiWorker.terminate();aiWorker=null}await aiPreflight(modelId);const made=await createByStrategy(modelId,{assignGlobal:true});aiEngine=made.engine;aiEngineMode=made.mode;aiSelectedModel=modelId;aiReady=true;setAIStatus(`${modelId} loaded locally via ${made.mode} engine. Runtime: ${webllmRuntimeSource}`);await refreshAICacheStates();renderAIModelCatalog();renderAIEnvironment()}catch(err){aiEngine=null;aiReady=false;const f=classifyAIError(err,'load',aiEngineMode);showAIDiagnostics(f);setAIStatus(`WebLLM load failed (${f.kind}): ${f.hint}`);toast('WebLLM model could not load')}finally{aiBusy=false;if(btn)btn.disabled=false;syncAIControls()}}
async function downloadAIModel(modelId=aiSelectedModel,{safeMode=false}={}){if(aiBusy)return;if(!confirm(`${safeMode?'Retry download/cache':'Download/cache'} ${modelId}? Model artifacts can be large. This direct-engine edition verifies WebLLM’s local cache before reporting success.`))return;aiBusy=true;aiReady=false;aiLastFailure=null;syncAIControls();const backend=safeMode?'cache':getAIBackend();const strategy=safeMode?'direct-only':getAIStrategy();let stage='preflight',temp=null,tempWorker=null;try{aiSelectedModel=modelId;if(safeMode){if($('#aiBackend'))$('#aiBackend').value='cache';if($('#aiStrategy'))$('#aiStrategy').value='direct-only'}await aiPreflight(modelId,backend);stage='cache-check';if(await verifyAICache(modelId,backend)){setAIStatus(`${modelId} is already fully cached in ${backend}.`);toast('Model already cached');await refreshAICacheStates();renderAIModelCatalog();return}stage='engine-download';const made=await createByStrategy(modelId,{backend,cacheOnly:true,assignGlobal:false,strategy});temp=made.engine;aiEngineMode=made.mode;tempWorker=temp.__txWorker||null;stage='unload';await temp.unload();if(tempWorker)tempWorker.terminate();temp=null;tempWorker=null;stage='verify-cache';if(!await verifyAICache(modelId,backend))throw new Error('Engine initialization completed, but hasModelInCache returned false; cache appears incomplete');setAIStatus(`${modelId} downloaded and verified in ${backend} via ${aiEngineMode} engine. GPU memory released.`);toast('Model download verified');await refreshAICacheStates();renderAIModelCatalog();renderAIEnvironment()}catch(e){try{if(temp)await temp.unload()}catch{}try{tempWorker?.terminate()}catch{}const f=classifyAIError(e,stage,aiEngineMode);showAIDiagnostics(f);setAIStatus(`Model download failed at ${stage} (${f.kind}). ${f.hint}`);toast(`Model download failed: ${f.kind}`)}finally{aiBusy=false;syncAIControls()}}
async function retryAISafest(){if(!aiLastFailure)return;const model=aiLastFailure.model||aiSelectedModel;await downloadAIModel(model,{safeMode:true})}
async function deleteAIModelCache(modelId){if(!confirm(`Delete cached model data for ${modelId}? This will require re-downloading it later.`))return;try{const webllm=await getWebLLM();if(aiReady&&modelId===aiSelectedModel)await unloadAI();await webllm.deleteModelAllInfoInCache(modelId,getAIAppConfig(webllm));await refreshAICacheStates();renderAIModelCatalog();renderAIEnvironment();toast('Cached model deleted')}catch(e){toast('Cache deletion failed: '+e.message)}}
async function unloadAI(){try{if(aiEngine)await aiEngine.unload()}catch{}aiEngine=null;aiReady=false;aiEngineMode='';if(aiWorker){aiWorker.terminate();aiWorker=null}const status=$('#aiStatus');if(status)status.textContent=`${aiSelectedModel} unloaded from GPU memory. Cached artifacts, if present, remain in browser storage.`;syncAIControls();renderAIEnvironment()}
async function probeAIURL(label,url){const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),9000);try{let res;try{res=await fetch(url,{method:'HEAD',cache:'no-store',mode:'cors',signal:ctrl.signal});clearTimeout(timer);return{label,url,ok:res.ok,status:res.status,note:res.ok?'reachable with CORS':'HTTP '+res.status}}catch(corsErr){try{res=await fetch(url,{method:'HEAD',cache:'no-store',mode:'no-cors',signal:ctrl.signal});clearTimeout(timer);return{label,url,ok:true,status:0,note:'network route reachable; CORS/HTTP status not readable'}}catch(e){throw corsErr}}}catch(e){clearTimeout(timer);return{label,url,ok:false,status:0,note:String(e?.message||e)}}}
async function testAIHosts(){const el=$('#aiHostProbe');if(!el)return;try{if(!aiCatalog.length)await loadModelCatalog();const rec=getAIModelRecord(aiSelectedModel);if(!rec)throw new Error('Select a model first');el.textContent='Testing runtime and selected model hosts…';const modelBase=String(rec.model||'').replace(/\/$/,'');const probes=[];for(const cdn of WEBLLM_CDNS)probes.push([cdn.label,cdn.url]);if(modelBase)probes.push(['Hugging Face model config',modelBase+'/resolve/main/mlc-chat-config.json']);if(rec.model_lib)probes.push(['Compiled WebGPU library',rec.model_lib]);const results=[];for(const [label,url] of probes)results.push(await probeAIURL(label,url));el.innerHTML=`<div class="host-probe-list">${results.map(r=>`<div class="host-probe ${r.ok?'ok':'bad'}"><b>${r.ok?'✓':'×'} ${esc(r.label)}</b><span>${esc(r.note)}</span><small>${esc((()=>{try{return new URL(r.url).hostname}catch{return r.url}})())}</small></div>`).join('')}</div><p class="muted">A successful host probe does not prove a multi-gigabyte transfer will complete, but a failed probe identifies a network route that engine switching cannot repair.</p>`}catch(e){el.textContent='Host test failed: '+String(e?.message||e)}}
async function getAIResilience(){if(aiResilienceModule)return aiResilienceModule;aiResilienceModule=await import('./ai-resilience.js');return aiResilienceModule}
function setAIResilienceStatus(html){const el=$('#aiResilienceStatus');if(el)el.innerHTML=html}
async function selectedAIAssetPlan({force=false}={}){if(aiLastAssetPlan&&!force&&aiLastAssetPlan.model_id===aiSelectedModel)return aiLastAssetPlan;const rec=getAIModelRecord(aiSelectedModel)||WEBLLM_BUILTIN_FALLBACK,mod=await getAIResilience();setAIResilienceStatus('Reading model manifests and constructing the file-level cache plan…');aiLastAssetPlan=await mod.buildModelAssetPlan(rec,{runtimeUrls:[]});return aiLastAssetPlan}
async function stageSelectedAIModel(){if(aiBusy)return;aiBusy=true;const bar=$('#aiStageProgress');if(bar)bar.style.width='0%';try{const mod=await getAIResilience(),plan=await selectedAIAssetPlan({force:true});setAIResilienceStatus(`<b>Staging ${esc(plan.model_id)}</b> · ${plan.metadata.shards} weight shards · retrying failed files individually.`);const result=await mod.stagePlanWithServiceWorker(plan,{retries:3,onProgress:m=>{if(bar)bar.style.width=`${Math.round((m.done/m.total)*100)}%`;setAIResilienceStatus(`<b>${esc(plan.model_id)}</b><br>${m.done}/${m.total} assets · ${esc(m.status)} · ${esc((()=>{try{return new URL(m.url).pathname.split('/').pop()}catch{return m.url}})())}`)}});const check=await mod.verifyPlan(plan);setAIResilienceStatus(`<b>Offline staging complete.</b> ${check.cached}/${check.total} assets verified in the PWA AI cache. ${result.downloaded} downloaded this run; ${result.cached} were already cached.`);toast('AI model assets staged for offline use')}catch(e){const f=classifyAIError(e,'pwa-model-stage');showAIDiagnostics(f);setAIResilienceStatus(`<b>Staging stopped (${esc(f.kind)}).</b> ${esc(f.hint)}<br><small>${esc(String(e?.message||e))}</small><br><span class="muted">If the browser cannot reach the host, use the offline model-pack folder importer below.</span>`)}finally{aiBusy=false;syncAIControls()}}
async function installHostedAIModelPack(){try{const rec=getAIModelRecord(aiSelectedModel)||WEBLLM_BUILTIN_FALLBACK,mod=await getAIResilience();setAIResilienceStatus(`Checking this site for a hosted offline pack for <b>${esc(rec.model_id)}</b>…`);const r=await mod.installHostedPack(rec);setAIResilienceStatus(`<b>Hosted offline pack installed into the PWA cache.</b> ${r.installed} files · ${mod.formatBytes(r.bytes)}. WebLLM can now request its normal URLs while the service worker supplies the local copies.`);toast('Hosted AI pack installed')}catch(e){setAIResilienceStatus(`<b>No usable hosted pack.</b> ${esc(String(e?.message||e))}<br><span class="muted">Use the folder importer or PWA staging instead.</span>`)}}
async function verifySelectedAIStage(){try{const mod=await getAIResilience(),plan=await selectedAIAssetPlan();const s=await mod.verifyPlan(plan);setAIResilienceStatus(`<b>${s.complete?'Complete':'Incomplete'} staged model.</b> ${s.cached}/${s.total} assets cached.${s.missing.length?` Missing ${s.missing.length}: ${esc(s.missing.slice(0,4).map(x=>{try{return new URL(x).pathname.split('/').pop()}catch{return x}}).join(', '))}${s.missing.length>4?' …':''}`:''}`)}catch(e){setAIResilienceStatus('Verification failed: '+esc(String(e?.message||e)))}}
async function clearSelectedAIStage(){if(!confirm('Clear the dedicated PWA-staged assets for the selected model? WebLLM’s own cache backend is separate.'))return;try{const mod=await getAIResilience(),plan=await selectedAIAssetPlan(),n=await mod.clearPlan(plan);setAIResilienceStatus(`Cleared ${n} staged assets for ${esc(plan.model_id)}.`);toast('PWA staged assets cleared')}catch(e){setAIResilienceStatus('Clear failed: '+esc(String(e?.message||e)))}}
async function installSelectedAIModelPack(files){try{const rec=getAIModelRecord(aiSelectedModel)||WEBLLM_BUILTIN_FALLBACK,mod=await getAIResilience();setAIResilienceStatus('Installing local model pack into the PWA AI cache…');const r=await mod.installLocalFolderPack([...files],rec,{runtimeTarget:'./vendor/webllm-0.2.85.mjs'});aiLastAssetPlan=r.plan;setAIResilienceStatus(`<b>Local pack installed.</b> ${r.installed} files · ${mod.formatBytes(r.bytes)}.${r.runtimeInstalled?' Local WebLLM runtime included.':' Model artifacts installed; runtime will use local vendor if separately installed, otherwise CDN fallback.'}<br><span class="muted">Reload the page once if the service worker was newly installed, then load the model normally.</span>`);toast('Offline model pack installed')}catch(e){setAIResilienceStatus(`<b>Pack install failed.</b> ${esc(String(e?.message||e))}`)}}
async function testAIEndpoint(){const base=$('#aiEndpointBase')?.value.trim().replace(/\/$/,'')||'',model=$('#aiEndpointModel')?.value.trim()||'',key=$('#aiEndpointKey')?.value||'',out=$('#aiEndpointStatus');if(!base||!model){out.textContent='Enter a base URL and model name first.';return}out.textContent='Testing endpoint…';try{const headers={'Content-Type':'application/json'};if(key)headers.Authorization=`Bearer ${key}`;const r=await fetch(base+'/chat/completions',{method:'POST',headers,body:JSON.stringify({model,messages:[{role:'user',content:'Reply with exactly: ready'}],max_tokens:8,temperature:0})});if(!r.ok)throw new Error(`${r.status} ${r.statusText}: ${(await r.text()).slice(0,240)}`);const j=await r.json();out.textContent='Endpoint reachable. Response: '+String(j.choices?.[0]?.message?.content||'received').slice(0,120)}catch(e){out.textContent='Endpoint test failed: '+String(e?.message||e)}}
async function runEndpointAI(){const base=$('#aiEndpointBase')?.value.trim().replace(/\/$/,'')||'',model=$('#aiEndpointModel')?.value.trim()||'',key=$('#aiEndpointKey')?.value||'',prompt=$('#aiPrompt')?.value.trim()||'';if(!base||!model||!prompt)throw new Error('Local endpoint is not configured');const headers={'Content-Type':'application/json'};if(key)headers.Authorization=`Bearer ${key}`;const r=await fetch(base+'/chat/completions',{method:'POST',headers,body:JSON.stringify({model,messages:[{role:'system',content:buildAISystemPrompt(analyzeAITask(prompt))},{role:'user',content:augmentAIUserPrompt(prompt,analyzeAITask(prompt)).slice(0,16000)}],temperature:Math.max(0,Math.min(1.5,Number($('#aiTemperature')?.value||0.3))),max_tokens:Math.max(64,Math.min(2048,Number($('#aiMaxTokens')?.value||800)))})});if(!r.ok)throw new Error(`${r.status} ${r.statusText}`);const j=await r.json();return j.choices?.[0]?.message?.content||'No output'}
async function maybeEscalateAIForTask(task){if($('#aiAutoEscalate')?.checked===false||!aiCatalog.length)return false;const current=getAIModelRecord(aiSelectedModel);if(current&&modelTaskFitness(current,task)>=modelTaskFitness(recommendModelForTask(task)||current,task)-2)return false;const upgrade=recommendModelForTask(task,{cachedOnly:true});if(!upgrade||upgrade.model_id===aiSelectedModel)return false;const old=aiSelectedModel;aiSelectedModel=upgrade.model_id;setAIStatus(`Adaptive planner: switching from ${old} to cached ${upgrade.model_id} for ${task.mode} planning…`);await loadAI(upgrade.model_id);return aiReady}
async function runResilientAI(){const prompt=$('#aiPrompt')?.value.trim();if(!prompt)return toast('Enter a planning request first');const task=analyzeAITask(prompt),out=$('#aiOutput'),policy=window.TXAIDeployment?.policy?.()||{routing:'auto',preferServerHeavy:true,allowRemote:false},pub=window.TXPublicInference?.policy?.()||{enabled:false,preferHeavy:false,tryBeforeDeterministic:false},base=$('#aiEndpointBase')?.value.trim()||'',model=$('#aiEndpointModel')?.value.trim()||'',isLocal=/^https?:\/\/(localhost|127\.0\.0\.1|\[::1\])(?::|\/|$)/i.test(base),endpointAllowed=!!(base&&model&&(isLocal||policy.allowRemote));renderAITaskAssessment();out.textContent=`Adaptive planner: ${task.mode} request detected. Routing across local + hosted fallbacks…`;const preferServer=endpointAllowed&&(policy.routing==='server'||(policy.routing==='auto'&&policy.preferServerHeavy&&['comprehensive','expert'].includes(task.mode)));if(preferServer){try{out.textContent=await runEndpointAI();if(!isWeakAIResponse(out.textContent,task))return}catch(e){out.textContent='Local runtime unavailable or insufficient; continuing through other inference paths. '+String(e?.message||e)+'\n\n'}}const preferPublic=!!(window.TXPublicInference&&pub.enabled&&pub.preferHeavy&&['comprehensive','expert'].includes(task.mode));if(preferPublic){try{const r=await window.TXPublicInference.generate({prompt:augmentAIUserPrompt(prompt,task),system:buildAISystemPrompt(task),taskMode:task.mode,temperature:Number($('#aiTemperature')?.value||.25),maxTokens:Number($('#aiMaxTokens')?.value||1600)});out.textContent=r.text;if(!isWeakAIResponse(out.textContent,task))return}catch(e){out.textContent='Public hosted inference unavailable/quota-limited; falling back locally. '+String(e?.message||e)+'\n\n'}}if(policy.routing!=='server'&&aiReady&&aiEngine){try{await maybeEscalateAIForTask(task)}catch{}await runAI({task});return}if(window.TXPublicInference&&pub.enabled&&pub.tryBeforeDeterministic&&!preferPublic){try{const r=await window.TXPublicInference.generate({prompt:augmentAIUserPrompt(prompt,task),system:buildAISystemPrompt(task),taskMode:task.mode,temperature:Number($('#aiTemperature')?.value||.25),maxTokens:Number($('#aiMaxTokens')?.value||1600)});out.textContent=r.text;if(!isWeakAIResponse(out.textContent,task))return}catch(e){out.textContent='Public hosted inference unavailable; continuing with configured endpoint/deterministic planning. '+String(e?.message||e)+'\n\n'}}if(endpointAllowed){try{out.textContent=await runEndpointAI();if(!isWeakAIResponse(out.textContent,task))return}catch(e){out.textContent='Configured endpoint unavailable or insufficient; continuing with deterministic planning. '+String(e?.message||e)+'\n\n'}}out.textContent=deterministicPlannerText(prompt,task)}

async function runAI({task=null}={}){const p=$('#aiPrompt').value.trim();if(!p||!aiReady||!aiEngine)return;task=task||analyzeAITask(p);$('#runAI').disabled=true;const current=getAIModelRecord(aiSelectedModel),fit=current?taskFitLabel(current,task):'Unknown fit';$('#aiOutput').textContent=`Generating ${task.mode} plan locally with ${aiSelectedModel}… ${fit}`;const userTemp=Math.max(0,Math.min(1.5,Number($('#aiTemperature')?.value||0.25))),userMax=Math.max(64,Math.min(2048,Number($('#aiMaxTokens')?.value||1600))),autoMax=task.mode==='expert'?2048:task.mode==='comprehensive'?Math.max(1600,userMax):userMax,system=buildAISystemPrompt(task),user=augmentAIUserPrompt(p,task).slice(0,16000);try{let r=await aiEngine.chat.completions.create({messages:[{role:'system',content:system},{role:'user',content:user}],temperature:Math.min(userTemp,task.mode==='fast'?0.5:0.35),max_tokens:autoMax});let text=r.choices?.[0]?.message?.content||'';if(isWeakAIResponse(text,task)){const correction=`Your previous response was too generic or incorrectly refused an ordinary planning task. Complete it now. Do not apologize or redirect the user. Use the scaffold, state assumptions instead of inventing facts, and produce concrete phases, owners, interventions, metrics, risks and verification needs.`;r=await aiEngine.chat.completions.create({messages:[{role:'system',content:system},{role:'user',content:user},{role:'assistant',content:text.slice(0,1800)},{role:'user',content:correction}],temperature:0.15,max_tokens:Math.max(autoMax,1800)});text=r.choices?.[0]?.message?.content||text}if(isWeakAIResponse(text,task)){text=`${deterministicPlannerText(p,task)}\n\n---\n\nLocal-model note: the active model (${aiSelectedModel}) did not produce a sufficiently substantive expansion after retry. The deterministic plan above is shown instead. Consider the task-quality recommendation in the AI Lab and load a stronger compatible model for richer prose.`}$('#aiOutput').textContent=text}catch(err){$('#aiOutput').textContent=`Generation error: ${String(err?.message||err)}\n\n${deterministicPlannerText(p,task)}`}finally{$('#runAI').disabled=false}}
window.TXAIChain={
  status:()=>({ready:aiReady,model:aiSelectedModel,engineMode:aiEngineMode,public:window.TXPublicInference?.policy?.()}),
  generate:async({prompt,complexity='comprehensive',stageTitle=''})=>{const task=analyzeAITask(prompt);task.mode=complexity==='expert'?'expert':complexity==='fast'?'fast':'comprehensive';const system=`You are executing a bounded Meta-Chain stage inside Texas Master Systems OS. Complete the planning work directly. Separate attached/verified evidence from inference, assumptions and verification needs. Produce concrete actions, owners, handoffs, metrics, acceptance tests and failure modes. Never substitute “contact stakeholders” for doing the analysis; include stakeholders as participants. Stage: ${stageTitle}`;const max=task.mode==='expert'?2048:task.mode==='comprehensive'?1800:900,pub=window.TXPublicInference?.policy?.()||{enabled:false,preferHeavy:false,tryBeforeDeterministic:false};if(window.TXPublicInference&&pub.enabled&&pub.preferHeavy&&['comprehensive','expert'].includes(task.mode)){try{const r=await window.TXPublicInference.generate({prompt:String(prompt).slice(0,24000),system,taskMode:task.mode,temperature:task.mode==='fast'?0.3:0.2,maxTokens:max});if(r.text&&!isWeakAIResponse(r.text,task))return{text:r.text,model:r.model,mode:r.provider||'public'}}catch{}}try{if(aiCatalog.length)await maybeEscalateAIForTask(task)}catch{}if(aiReady&&aiEngine){try{let r=await aiEngine.chat.completions.create({messages:[{role:'system',content:system},{role:'user',content:String(prompt).slice(0,16000)}],temperature:task.mode==='fast'?0.3:0.2,max_tokens:max});let text=r.choices?.[0]?.message?.content||'';if(isWeakAIResponse(text,task)){r=await aiEngine.chat.completions.create({messages:[{role:'system',content:system},{role:'user',content:String(prompt).slice(0,16000)},{role:'assistant',content:text.slice(0,1200)},{role:'user',content:'Retry. The prior answer was too generic. Produce the requested implementation artifact now, with concrete actions, owners, handoffs, metrics, assumptions, evidence gaps and failure modes.'}],temperature:0.1,max_tokens:max});text=r.choices?.[0]?.message?.content||text}if(text&&!isWeakAIResponse(text,task))return{text,model:aiSelectedModel,mode:aiEngineMode||'webllm'}}catch(e){if(!pub.enabled)return{text:'',model:aiSelectedModel,mode:'error',error:String(e?.message||e)}}}if(window.TXPublicInference&&pub.enabled&&pub.tryBeforeDeterministic){try{const r=await window.TXPublicInference.generate({prompt:String(prompt).slice(0,24000),system,taskMode:task.mode,temperature:task.mode==='fast'?0.3:0.2,maxTokens:max});if(r.text&&!isWeakAIResponse(r.text,task))return{text:r.text,model:r.model,mode:r.provider||'public'}}catch{}}return{text:'',model:'deterministic',mode:'fallback'}}
};
function runDeterministicPlanner(){const prompt=($('#aiPrompt')?.value||'').trim();$('#aiOutput').textContent=deterministicPlannerText(prompt,analyzeAITask(prompt))}

// ---------- search ----------
function searchIndex(){const arr=[];if(window.TXMetaChain)arr.push(...window.TXMetaChain.searchEntries());ROUTES.forEach(r=>arr.push({title:r.label,body:r.group,route:r.id}));DOMAINS.forEach(d=>{d.modules.forEach(m=>arr.push({title:m,body:d.mission,route:'domain-'+d.id}));arr.push({title:d.principle,body:d.label,route:'domain-'+d.id});const z=DOMAIN_DEPTH[d.id]||{};Object.values(z).flat().forEach(v=>arr.push({title:v,body:d.label,route:'domain-'+d.id}))});GUIDES.forEach(g=>arr.push({title:g.title,body:g.one+' '+g.advanced,route:'guides'}));EVIDENCE.forEach(e=>arr.push({title:e.title,body:e.note,route:'evidence'}));STATUS_FACTS.forEach(e=>arr.push({title:e.title,body:e.fact+' '+e.limits,route:'status'}));return arr}
const SEARCH=searchIndex();function runSearch(q){q=q.trim().toLowerCase();const el=$('#searchResults');if(!q){el.innerHTML='<div class="empty">Type to search all systems.</div>';return}const hits=SEARCH.filter(x=>(x.title+' '+x.body).toLowerCase().includes(q)).slice(0,30);el.innerHTML=hits.map(x=>`<a class="search-hit" href="#/${x.route}"><b>${esc(x.title)}</b><br><small class="muted">${esc(x.body.slice(0,150))}</small></a>`).join('')||'<div class="empty">No matches.</div>'}
function openSearch(){const p=$('#searchPanel');p.classList.add('open');$('#globalSearch').focus();runSearch($('#globalSearch').value)}

function initFx(){const c=$('#fx'),ctx=c.getContext('2d');let w,h,pts=[];function resize(){w=c.width=innerWidth*devicePixelRatio;h=c.height=innerHeight*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0);pts=Array.from({length:Math.min(78,Math.floor(innerWidth/18))},()=>({x:Math.random()*innerWidth,y:Math.random()*innerHeight,vx:(Math.random()-.5)*.18,vy:(Math.random()-.5)*.18,r:Math.random()*1.6+.4}))}function frame(){if(state.settings.reduceMotion)return;ctx.clearRect(0,0,innerWidth,innerHeight);ctx.fillStyle='rgba(130,230,255,.55)';pts.forEach(p=>{p.x+=p.vx;p.y+=p.vy;if(p.x<0||p.x>innerWidth)p.vx*=-1;if(p.y<0||p.y>innerHeight)p.vy*=-1;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,7);ctx.fill()});ctx.strokeStyle='rgba(105,210,235,.08)';for(let i=0;i<pts.length;i++)for(let j=i+1;j<pts.length;j++){const a=pts[i],b=pts[j],dx=a.x-b.x,dy=a.y-b.y;if(dx*dx+dy*dy<14000){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke()}}requestAnimationFrame(frame)}addEventListener('resize',resize);resize();frame()}
function syncNavButton(){const mobile=matchMedia('(max-width:900px)').matches;const open=mobile?document.body.classList.contains('nav-open'):!document.body.classList.contains('nav-collapsed');const b=$('#navToggle');b.setAttribute('aria-expanded',String(open));b.setAttribute('aria-label',open?'Close navigation':'Open navigation')}
function toggleNavigation(){const mobile=matchMedia('(max-width:900px)').matches;if(mobile){document.body.classList.toggle('nav-open')}else{document.body.classList.toggle('nav-collapsed');localStorage.setItem('txmaster.navCollapsed',document.body.classList.contains('nav-collapsed')?'1':'0')}syncNavButton()}
function closeMobileNav(){document.body.classList.remove('nav-open');syncNavButton()}
function initGlobal(){if(localStorage.getItem('txmaster.navCollapsed')==='1'&&!matchMedia('(max-width:900px)').matches)document.body.classList.add('nav-collapsed');addEventListener('hashchange',render);$('#navToggle').setAttribute('aria-controls','sidebar');$('#navToggle').onclick=toggleNavigation;$('#navScrim').onclick=closeMobileNav;addEventListener('resize',()=>{if(!matchMedia('(max-width:900px)').matches)document.body.classList.remove('nav-open');syncNavButton()});$('#searchBtn').onclick=openSearch;$('#closeSearch').onclick=()=>$('#searchPanel').classList.remove('open');$('#globalSearch').oninput=e=>runSearch(e.target.value);$('#settingsBtn').onclick=openSettings;$('#collabBtn').onclick=openCollab;$$('[data-close-modal]').forEach(b=>b.onclick=()=>closeModal(b.dataset.closeModal));$$('.modal').forEach(m=>m.addEventListener('click',e=>{if(e.target===m)closeModal(m.id)}));document.addEventListener('keydown',e=>{if(e.key==='Escape'){$$('.modal.open').forEach(m=>closeModal(m.id));$('#searchPanel').classList.remove('open');closeMobileNav()}const modal=$('.modal.open');if(e.key==='Tab'&&modal){const f=$$('button:not([disabled]),input:not([disabled]),select:not([disabled]),textarea:not([disabled]),a[href]',modal).filter(x=>x.offsetParent!==null);if(f.length){const first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}});if('serviceWorker'in navigator&&location.protocol!=='file:')navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(reg=>reg.update().catch(()=>{})).catch(()=>{});window.addEventListener('online',()=>toast('Network available'));window.addEventListener('offline',()=>toast('Offline: local tools remain available'));syncNavButton()}
(async function boot(){loadSettings();state.db=await openDB();await reloadRecords();initGlobal();initSplash();initFx();if(!location.hash)location.hash='#/home';else render();})();

